import { money, percent } from './format';
import type { PerformancePoint, PerformanceSummary } from './types';

type CurveMode = 'assets' | 'nav';
type RangeMode = 'ALL' | '1Y' | '3Y';

function rangePoints(points: PerformancePoint[], range: RangeMode): PerformancePoint[] {
  if (range === 'ALL' || points.length < 2) return points;
  const end = new Date(points.at(-1)!.date).getTime();
  const years = range === '1Y' ? 1 : 3;
  const cutoff = new Date(end);
  cutoff.setFullYear(cutoff.getFullYear() - years);
  return points.filter((point) => new Date(point.date).getTime() >= cutoff.getTime());
}

function svg(points: PerformancePoint[], mode: CurveMode): string {
  if (points.length < 2) return '<div class="overview-empty"><strong>等待第二份资产记录</strong><p>首份确认只建立基线，不会伪造历史收益；以后保存持仓会逐步形成真实资产轨迹。</p></div>';
  const width = 1000;
  const height = 310;
  const values = points.map((point) => mode === 'assets' ? point.totalAssets : point.nav);
  const min = Math.min(...values);
  const max = Math.max(...values);
  const span = Math.max(max - min, Math.abs(max) * .001, .0001);
  const coordinates = values.map((value, index) => ({
    x: 22 + index / Math.max(1, values.length - 1) * (width - 44),
    y: height - 24 - (value - min) / span * (height - 54),
  }));
  const path = coordinates.map((point, index) => `${index ? 'L' : 'M'}${point.x.toFixed(1)},${point.y.toFixed(1)}`).join(' ');
  const area = `${path} L${coordinates.at(-1)!.x.toFixed(1)},${height - 22} L${coordinates[0]!.x.toFixed(1)},${height - 22} Z`;
  const flows = points.map((point, index) => point.cashFlow === 0 ? '' : `<circle cx="${coordinates[index]!.x.toFixed(1)}" cy="${coordinates[index]!.y.toFixed(1)}" r="4"><title>${point.date} 净现金流 ${money(point.cashFlow)}</title></circle>`).join('');
  const first = points[0]!;
  const last = points.at(-1)!;
  const minLabel = mode === 'assets' ? money(min) : percent(min - 1);
  const maxLabel = mode === 'assets' ? money(max) : percent(max - 1);
  return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${mode === 'assets' ? '家庭总资产规模曲线' : '现金流中性收益净值曲线'}，${first.date}至${last.date}"><path class="asset-curve-area" d="${area}"/><path class="asset-curve-line" d="${path}"/>${flows}<text x="22" y="18">${maxLabel}</text><text x="22" y="${height - 5}">${minLabel}</text><text class="curve-date" x="22" y="${height - 28}">${first.date}</text><text class="curve-date end" x="${width - 22}" y="${height - 28}">${last.date}</text></svg>`;
}

function periodMetrics(points: PerformancePoint[]): { profit: number | null; returnValue: number | null; cashFlow: number } {
  if (points.length < 2) return { profit: null, returnValue: null, cashFlow: 0 };
  const first = points[0]!;
  const last = points.at(-1)!;
  const cashFlow = points.slice(1).reduce((sum, point) => sum + point.cashFlow, 0);
  return {
    profit: last.totalAssets - first.totalAssets - cashFlow,
    returnValue: last.nav / first.nav - 1,
    cashFlow,
  };
}

export function bindAssetOverview(summary: PerformanceSummary): void {
  const chart = document.querySelector<HTMLElement>('#asset-curve');
  if (!chart) return;
  let mode: CurveMode = 'assets';
  let range: RangeMode = 'ALL';
  const render = () => {
    const points = rangePoints(summary.points, range);
    chart.innerHTML = svg(points, mode);
    const metrics = periodMetrics(points);
    const profit = document.querySelector<HTMLElement>('#overview-period-profit');
    const returnValue = document.querySelector<HTMLElement>('#overview-period-return');
    const flow = document.querySelector<HTMLElement>('#overview-period-flow');
    if (profit) profit.textContent = money(metrics.profit);
    if (returnValue) returnValue.textContent = percent(metrics.returnValue);
    if (flow) flow.textContent = money(metrics.cashFlow);
    document.querySelectorAll<HTMLButtonElement>('[data-curve-mode]').forEach((button) => button.setAttribute('aria-pressed', String(button.dataset.curveMode === mode)));
    document.querySelectorAll<HTMLButtonElement>('[data-overview-range]').forEach((button) => button.setAttribute('aria-pressed', String(button.dataset.overviewRange === range)));
  };
  document.querySelectorAll<HTMLButtonElement>('[data-curve-mode]').forEach((button) => button.addEventListener('click', () => { mode = button.dataset.curveMode as CurveMode; render(); }));
  document.querySelectorAll<HTMLButtonElement>('[data-overview-range]').forEach((button) => button.addEventListener('click', () => { range = button.dataset.overviewRange as RangeMode; render(); }));
  document.querySelector<HTMLButtonElement>('[data-hide-amounts]')?.addEventListener('click', (event) => {
    const button = event.currentTarget as HTMLButtonElement;
    const hidden = document.querySelector('#main')?.classList.toggle('amounts-hidden') ?? false;
    button.setAttribute('aria-pressed', String(hidden));
    button.textContent = hidden ? '显示金额' : '隐藏金额';
  });
  render();
}
