function targetReason(asset: PublicAsset): string {
  const signals = asset.confirmedSignals;
  if (asset.assetClass === 'EQUITY') {
    const group = asset.targetFormation.allocationGroup === 'CORE' ? '核心组' : asset.targetFormation.allocationGroup === 'SATELLITE' ? '卫星组' : '权益仓';
    return `确认日趋势 ${number(signals.trendScore)}、相对强弱 ${number(signals.relativeStrength)}、波动惩罚 ${number(signals.volPenalty)}，形成吸引力 ${number(asset.targetFormation.attractiveness, 3)}；经组内上下限归一化后占${group} ${percent(asset.targetFormation.finalGroupShare)}。`;
  }
  return `确认日趋势 ${number(signals.trendScore)}；黄金与国债按防御公式分配，最终占防御仓 ${percent(asset.targetFormation.finalGroupShare)}，并满足组合绝对上下限。`;
}

function decisionTimelineMarkup(snapshot: PublicSnapshot): string {
  const decisions = uniqueConfirmedDecisions(snapshot);
  const start = Math.max(0, decisions.length - 6);
  const entries = decisions.slice(start).map((entry, offset) => ({
    entry,
    previous: decisions[start + offset - 1],
  })).reverse();
  const rows = entries.map(({ entry, previous }, index) => {
    const changes = snapshot.assets.map((asset) => ({
      asset,
      change: previous ? entry.targetWeights[asset.code] - previous.targetWeights[asset.code] : null,
    }));
    const largestChange = previous
      ? [...changes].sort((left, right) => Math.abs(right.change ?? 0) - Math.abs(left.change ?? 0))[0]
      : undefined;
    const changeCopy = largestChange?.change != null
      ? `本期变化最大：${instrumentLabel(largestChange.asset.code, largestChange.asset.name)} ${signedPoints(largestChange.change)}`
      : '当前可用历史中的首个确认记录';
    const targets = snapshot.assets.map((asset) => `<div><dt>${escapeHtml(instrumentLabel(asset.code, asset.name))}</dt><dd>${percent(entry.targetWeights[asset.code])}</dd></div>`).join('');
    const regime = REGIME[entry.riskRegime as keyof typeof REGIME] ?? { zh: entry.riskRegime };
    return `<article class="decision-timeline-item ${index === 0 ? 'current' : ''}"><div class="decision-timeline-head"><time>${entry.signalDate ?? entry.date}</time><span>${escapeHtml(regime.zh)} · 风险评分 ${number(entry.riskScore * 100, 1)}</span><strong>权益目标 ${percent(entry.equityTarget)}</strong><small>${escapeHtml(changeCopy)}</small></div><dl>${targets}</dl></article>`;
  }).join('');
  return `<details class="decision-history reveal"><summary><span>最近 ${entries.length} 次月末确认</span><strong>展开历史目标与变化 →</strong></summary><div class="decision-timeline">${rows}</div><p>历史记录只追加、不覆盖；名称用于阅读，审计主键仍是 ETF 代码。</p></details>`;
}

