function assetRow(asset: PublicAsset, advice: AdviceResult): string {
  const current = advice.available ? advice.currentWeights[asset.code] : null;
  const execution = advice.rows.find((row) => row.code === asset.code);
  const target = execution?.targetWeight ?? asset.confirmedTarget;
  const gap = current == null ? null : target - current;
  const adjusted = Math.abs(target - asset.confirmedTarget) > .00005;
  return `<tr data-code="${asset.code}"><td><button type="button" class="asset-select" data-asset-code="${asset.code}"><strong>${escapeHtml(instrumentLabel(asset.code, asset.name))}</strong><span>${escapeHtml(asset.role)}</span></button></td><td>${percent(asset.return63)}</td><td>${percent(asset.return126)}</td><td>${percent(asset.return252)}</td><td>${percent(asset.forecastVol)}</td><td>${asset.relativeStrength == null ? '—' : number(asset.relativeStrength, 2)}</td><td>${percent(current)}</td><td><strong>${percent(target)}</strong>${adjusted ? `<small>模型 ${percent(asset.confirmedTarget)}</small>` : ''}</td><td class="${gap != null && gap > 0 ? 'positive' : gap != null && gap < 0 ? 'negative' : ''}">${percent(gap)}</td></tr>`;
}

function assetMobileRow(asset: PublicAsset, advice: AdviceResult): string {
  const current = advice.available ? advice.currentWeights[asset.code] : null;
  const execution = advice.rows.find((row) => row.code === asset.code);
  const target = execution?.targetWeight ?? asset.confirmedTarget;
  const gap = current == null ? null : target - current;
  const action = execution?.action === 'BUY' ? '建议增加' : execution?.action === 'SELL' ? '建议降低' : '无需操作';
  return `<details class="asset-mobile-row"><summary><span><strong>${escapeHtml(instrumentLabel(asset.code, asset.name))}</strong><small>${escapeHtml(asset.role)}</small></span><span><small>当前 / 家庭执行目标</small><strong>${percent(current)} / ${percent(target)}</strong></span><b class="${gap != null && gap > 0 ? 'positive' : gap != null && gap < 0 ? 'negative' : ''}">${percent(gap)}</b></summary><div class="asset-mobile-detail"><dl><div><dt>模型确认目标</dt><dd>${percent(asset.confirmedTarget)}</dd></div><div><dt>3 / 6 / 12 个月</dt><dd>${percent(asset.return63)} / ${percent(asset.return126)} / ${percent(asset.return252)}</dd></div><div><dt>预测波动</dt><dd>${percent(asset.forecastVol)}</dd></div><div><dt>相对强弱</dt><dd>${asset.relativeStrength == null ? '—' : number(asset.relativeStrength, 2)}</dd></div><div><dt>执行状态</dt><dd>${action}</dd></div></dl><p><strong>组合作用：</strong>${escapeHtml(asset.role)}。${escapeHtml(execution?.reason ?? '当前无执行解读。')}</p></div></details>`;
}

function householdDecisionBrief(snapshot: PublicSnapshot, advice: AdviceResult, portfolio: LocalPortfolio): string {
  const active = advice.rows.filter((row) => row.action !== 'NO TRADE');
  const nextAction = deriveHouseholdOperation(snapshot, portfolio, advice).current;
  const largestRisk = snapshot.diagnostics.riskContributions.reduce((left, right) => left.share >= right.share ? left : right);
  const largestRiskLabel = labelForCode(snapshot, largestRisk.code);
  const headline = snapshot.health.blocking
    ? '数据异常，暂停形成新建议'
    : !advice.available
      ? '目标已确认，等待录入家庭持仓'
      : !advice.adviceAllowed
        ? '执行输入不可信，暂停全部建议'
        : !advice.riskIncreaseAllowed
          ? '家庭政策待确认，仅保留降低风险的人工复核'
        : active.length
          ? `有 ${active.length} 只 ETF 越过执行边界`
          : '当前无需调仓，维持现有组合';
  const policy = portfolio.ipsPolicy;
  const householdState = !policy?.enabled
    ? '投资政策尚未建立'
    : `${policyStatusLabel(advice.policyStatus)} · 权益执行目标 ${percent(advice.operationalEquityTarget)}`;
  const householdNote = advice.riskIncreaseAllowed
    ? `已确认 · 下次复核 ${policy?.reviewDueDate ?? '未设置'}`
    : advice.riskIncreaseBlockedReason ?? '补全家庭资金边界后才允许增加风险';
  const actionState = `${nextAction.label}：${nextAction.detail}`;
  const outcome = snapshot.health.blocking ? '数据异常 · 禁止建议' : !advice.available ? '等待录入' : !advice.adviceAllowed ? '全部暂停' : !advice.riskIncreaseAllowed ? '政策待确认' : active.length ? '建议再平衡' : '无需操作';
  return `<div class="decision-brief reveal"><div class="decision-brief-title"><p class="eyebrow">家庭最终状态</p><span class="decision-outcome-label ${snapshot.health.blocking || !advice.adviceAllowed ? 'negative' : active.length ? 'warning' : 'positive'}">${outcome}</span><h2>${headline}</h2><p>模型先给风险目标，家庭政策只能降低风险，执行规则再决定是否需要行动。</p></div><div class="decision-brief-ledger"><div><span>数据与信号</span><strong class="${snapshot.health.blocking ? 'negative' : 'positive'}">${snapshot.health.blocking ? '阻断' : `${snapshot.meta.confirmedSignalDate} 已确认`}</strong><small>${snapshot.meta.confirmedEffectiveDate ?? '下一交易日'} 起可用</small></div><div><span>最大风险来源</span><strong>${escapeHtml(largestRiskLabel)} · ${percent(largestRisk.share)}</strong><small>风险贡献，不等同于持仓占比</small></div><div><span>家庭准备度</span><strong>${escapeHtml(householdState)}</strong><small>${escapeHtml(householdNote)}</small></div><div><span>本期下一步</span><strong>${escapeHtml(actionState)}</strong><small>最终决定由家庭人工复核</small></div></div></div>`;
}

function householdPolicyMarkup(advice: AdviceResult, portfolio: LocalPortfolio): string {
  const policy = portfolio.ipsPolicy;
  const buckets = portfolio.fundBuckets;
  if (!policy?.enabled) return '<div class="household-policy-summary reveal"><div><span>IPS Lite</span><strong>UNSET</strong></div><p>模型目标仍可查看；在家庭自行确认应急备用金、近期支出和权益上限前，系统不会给出增加风险的人工建议，也不构成个人适当性推荐。</p><button class="text-button" data-open-portfolio>建立家庭投资政策 →</button></div>';
  const caps = [policy.householdEquityCap, policy.liabilityEquityCap].filter((value): value is number => value != null && Number.isFinite(value));
  const capText = caps.length ? percent(Math.min(...caps)) : '未设置';
  const contextText = `${policy.horizonYears == null ? '期限未记录' : `投资期限 ${number(policy.horizonYears, 0)} 年`} · ${policy.maxTolerableDrawdown == null ? '承受损失未记录' : `可承受损失 ${percent(policy.maxTolerableDrawdown)}`}`;
  const needs = [buckets?.nearTermNeeds12Months, buckets?.nearTermNeeds13To36Months, buckets?.nearTermNeeds37To60Months].reduce<number>((sum, value) => sum + (value ?? 0), 0);
  return `<div class="household-policy-summary reveal"><div><span>IPS Lite</span><strong class="${advice.policyStatus === 'CONFIRMED' ? 'positive' : 'warning'}">${policyStatusLabel(advice.policyStatus)}</strong></div><dl><div><dt>家庭权益上限</dt><dd>${capText}</dd></div><div><dt>家庭执行目标</dt><dd>${percent(advice.operationalEquityTarget)}</dd></div><div><dt>未来60个月确定支出</dt><dd>${money(needs)}</dd></div><div><dt>组合内可投资现金</dt><dd>${money(buckets?.investableCash)}</dd></div><div><dt>背景记录</dt><dd>${contextText}</dd></div></dl><p>这些边界由家庭自行制定，只能降低模型风险，不构成个人适当性推荐。排除资金不会进入目标金额或买入建议。</p></div>`;
}

function adviceMarkup(snapshot: PublicSnapshot, advice: AdviceResult): string {
  if (snapshot.health.blocking) return '<div class="decision-note blocked"><strong>暂停建议</strong><p>数据健康检查未通过。请等待数据恢复，勿依据本次页面新增交易。</p></div>';
  if (!advice.available) return '<div class="decision-note"><strong>先录入本机持仓</strong><p>页面已显示模型目标；录入当前市值后，才会计算免交易带、50% 部分再平衡和建议金额。</p><button class="text-button" data-open-portfolio>录入持仓 →</button></div>';
  if (!advice.adviceAllowed) return `<div class="decision-note blocked"><strong>暂停建议</strong><p>${escapeHtml(advice.blockedReason ?? '本机执行输入不满足时效要求')}。更新后才会重新计算人工建议，既有模型目标不会因此改变。</p><button class="text-button" data-open-portfolio>更新本机输入 →</button></div>`;
  const active = advice.rows.filter((row) => row.action !== 'NO TRADE');
  if (!active.length && !advice.riskIncreaseAllowed) return `<div class="decision-note blocked"><strong>只读模型，暂停增加风险</strong><p>${escapeHtml(advice.riskIncreaseBlockedReason ?? '家庭政策尚未确认')}。</p><button class="text-button" data-open-portfolio>补全 IPS Lite →</button></div>`;
  if (!active.length) return '<div class="decision-note calm"><strong>无需操作</strong><p>所有资产均在免交易区间内。忽略细小偏差有助于控制成本和换手。</p></div>';
  const focus = advice.rows.filter((row) => row.action !== 'NO TRADE' || (Math.abs(row.gap) >= row.band && !row.reason.includes('免交易区间')));
  const quiet = advice.rows.filter((row) => !focus.includes(row));
  const rows = focus.map((row) => `<article class="advice-row ${row.action === 'NO TRADE' ? 'muted' : ''}"><div><span>${escapeHtml(labelForCode(snapshot, row.code))}</span><strong>${row.action === 'BUY' ? '建议增加' : row.action === 'SELL' ? '建议降低' : '本期不执行'}</strong></div><b class="${row.tradeWeight > 0 ? 'positive' : row.tradeWeight < 0 ? 'negative' : ''}">${money(row.suggestedAmount)}<small>${row.suggestedShares ? `${Math.abs(row.suggestedShares)} 股 · 估算成本 ${money(row.estimatedCost)}` : '不足一手或被执行规则拦截'}</small></b><dl class="advice-explain"><div><dt>为什么</dt><dd>当前 ${percent(row.currentWeight)}，家庭目标 ${percent(row.targetWeight)}，偏离 ${percent(row.gap)}，免交易带 ${percent(row.band)}</dd></div><div><dt>理论计划</dt><dd>${money(row.continuousAmount)}；${escapeHtml(row.reason)}</dd></div><div><dt>整手后</dt><dd>计划权重 ${percent(row.plannedWeight)}，剩余偏离 ${percent(row.remainingGap)}；人工复核，不是订单</dd></div></dl></article>`).join('');
  const quietMarkup = quiet.length ? `<details class="quiet-assets"><summary>其余 ${quiet.length} 只 ETF 处于免交易带或无需动作</summary><p>${quiet.map((row) => labelForCode(snapshot, row.code)).join('、')}</p></details>` : '';
  const policyWarning = advice.riskIncreaseAllowed ? '' : `<div class="decision-note blocked"><strong>家庭政策闸门生效</strong><p>${escapeHtml(advice.riskIncreaseBlockedReason ?? '')}。以下只保留可行的降低风险动作。</p></div>`;
  return `${policyWarning}<div class="advice-list">${rows}</div>${quietMarkup}`;
}

function monthlyOperationMarkup(snapshot: PublicSnapshot, portfolio: LocalPortfolio, advice: AdviceResult): string {
  const operation = deriveHouseholdOperation(snapshot, portfolio, advice);
  const statusLabel = { DONE: '完成', CURRENT: '当前', WAITING: '等待', BLOCKED: '阻断' } as const;
  const steps = operation.steps.map((step, index) => `<li class="${step.status.toLowerCase()}"><b>${String(index + 1).padStart(2, '0')}</b><span><strong>${escapeHtml(step.label)}</strong><small>${escapeHtml(step.detail)}</small></span><em>${statusLabel[step.status]}</em></li>`).join('');
  const action = operation.current.action === 'NONE'
    ? '<span class="operation-wait">保持只读并等待条件恢复</span>'
    : `<button type="button" class="primary" data-operation-action="${operation.current.action}">${escapeHtml(operation.current.label)}</button>`;
  return `<section class="monthly-operation reveal" aria-label="家庭月度操作中心"><div class="monthly-operation-lead"><p class="eyebrow">${operation.month} · MONTHLY OPERATIONS</p><span>已完成 ${operation.completed} / ${operation.total}</span><h2>${escapeHtml(operation.current.label)}</h2><p>${escapeHtml(operation.current.detail)}</p>${action}<small>所有步骤只负责人工复核与留痕，不连接券商、不提交订单。</small></div><ol>${steps}</ol></section>`;
}

function executionVarianceMarkup(snapshot: PublicSnapshot, portfolio: LocalPortfolio, record: LocalAdviceRecord): string {
  const variance = summarizeExecutionVariance(portfolio, record);
  if (!variance.available) return '<p class="legacy-execution-note">历史建议未保存计划成交金额，保留状态与成交回报，但不反推偏差。</p>';
  const rows = variance.rows.map((row) => `<tr><td>${escapeHtml(labelForCode(snapshot, row.code))}</td><td>${money(row.plannedAmount)}</td><td>${money(row.actualAmount)}</td><td class="${Math.abs(row.difference) > 1 ? 'warning' : ''}">${money(row.difference)}</td><td>${money(row.actualFee)}</td></tr>`).join('');
  return `<details class="execution-variance"><summary>查看计划与实际执行偏差</summary><div class="execution-variance-metrics"><span>计划成交额<strong>${money(variance.plannedNotional)}</strong></span><span>实际成交额<strong>${money(variance.actualNotional)}</strong></span><span>完成比例<strong>${percent(variance.completionRate)}</strong></span><span>费用差异<strong>${money(variance.feeDifference)}</strong></span><span>成交后最大目标偏差<strong>${percent(variance.maximumTargetDeviation)}</strong></span></div>${rows ? `<div class="table-scroll"><table><thead><tr><th>标的</th><th>计划金额</th><th>实际金额</th><th>金额差异</th><th>实际费用</th></tr></thead><tbody>${rows}</tbody></table></div>` : '<p>尚未登记真实成交。</p>'}</details>`;
}

function renderPortfolio(context: PageContext): string {
  const { snapshot, advice, portfolio } = context;
  const updated = advice.available ? date(portfolio.updatedAt, true) : '尚未录入';
  const policyActive = portfolio.ipsPolicy?.enabled;
  const equityCount = snapshot.assets.filter((asset) => asset.assetClass === 'EQUITY').length;
  const qdiiAssets = snapshot.assets.filter((asset) => snapshot.executionModel.qdiiCodes?.includes(asset.code) || asset.qdii);
  const premiumMeta = qdiiAssets.map((asset) => {
    const status = advice.premiumStatuses[asset.code] ?? '需要人工输入';
    const fresh = advice.premiumFreshByCode[asset.code] === true;
    return `<span>${escapeHtml(instrumentLabel(asset.code, asset.name))} 溢价门控 <strong class="${status.includes('WARNING') || !fresh ? 'negative' : ''}">${escapeHtml(status)}</strong></span>`;
  }).join('');
  const activeSnapshots = (portfolio.snapshots ?? []).filter((item) => !item.supersededBy);
  const cashFlows = activeCashFlows(portfolio);
  const flowRows = [...cashFlows].reverse().map((flow) => `<tr><td>${flow.date}</td><td>${flow.valuationEffectiveDate ?? '下一估值日自动匹配'}</td><td>${flow.type === 'CONTRIBUTION' ? '新增资金' : '取出资金'}</td><td class="${flow.type === 'CONTRIBUTION' ? 'positive' : 'negative'}">${money(flow.type === 'CONTRIBUTION' ? flow.amount : -flow.amount)}</td><td>${escapeHtml(flow.note || '—')}</td><td><button type="button" class="void-flow" data-void-cashflow="${escapeHtml(flow.id)}">作废</button></td></tr>`).join('');
  const latestSnapshotId = [...activeSnapshots].sort((a, b) => a.createdAt.localeCompare(b.createdAt)).at(-1)?.id ?? null;
  const currentAdviceSaved = (portfolio.adviceRecords ?? []).some((item) => item.signalDate === snapshot.meta.confirmedSignalDate && item.holdingsSnapshotId === latestSnapshotId);
  const adviceHistory = [...(portfolio.adviceRecords ?? [])].reverse().map((record) => {
    const status = latestAdviceStatus(portfolio, record.adviceId)?.status ?? record.status;
    const canReport = status === 'UNEXECUTED' || status === 'PARTIAL';
    const reports = (portfolio.executionReports ?? []).filter((item) => item.adviceId === record.adviceId);
    return `<article><div><span>${record.signalDate} 月末建议</span><strong>${adviceStatusLabel(status)}</strong><small>${record.effectiveDate} 起可用 · ${record.expiresAt} 失效 · 成交回报 ${reports.length} 笔</small></div><div class="advice-status-actions">${canReport ? `<button data-advice-status="PARTIAL" data-advice-id="${escapeHtml(record.adviceId)}">录入部分成交</button><button data-advice-status="EXECUTED" data-advice-id="${escapeHtml(record.adviceId)}">录入完成成交</button><button data-advice-status="SKIPPED" data-advice-id="${escapeHtml(record.adviceId)}">跳过</button>` : `<span>${status === 'EXECUTED' ? '成交与持仓已对账' : '只读历史'}</span>`}</div>${executionVarianceMarkup(snapshot, portfolio, record)}</article>`;
  }).join('');
  const deferrals = [...(portfolio.qdiiDeferrals ?? [])].reverse().map((item) => {
    const status = latestDeferralStatus(portfolio, item);
    const actions = status === 'DEFERRED' ? `<button data-deferral-status="REVIEWED" data-deferral-id="${escapeHtml(item.id)}">标记已复核</button>` : status === 'REVIEWED' ? `<button data-deferral-status="RELEASED" data-deferral-id="${escapeHtml(item.id)}">标记已释放</button>` : '';
    return `<li><strong>${escapeHtml(labelForCode(snapshot, item.code))}</strong><span>暂缓 ${money(item.withheldAmount)} · 暂存 ${escapeHtml(labelForCode(snapshot, item.parkedIn))}</span><small>${adviceStatusLabel(status)} · 下次按新月末目标重新计算，不自动追补</small>${actions}</li>`;
  }).join('');
  const reviewMonth = snapshot.meta.confirmedSignalDate.slice(0, 7);
  const currentReview = (portfolio.monthlyReviews ?? []).find((item) => item.month === reviewMonth);
  const operation = deriveHouseholdOperation(snapshot, portfolio, advice);
  const reviewReady = operation.steps.slice(0, -1).every((step) => step.status === 'DONE');
  const monthlyChecklist = `<form id="monthly-review-form" class="monthly-checklist"><div><p class="eyebrow">MONTHLY HOUSEHOLD REVIEW</p><h3>${reviewMonth} 家庭月度检查单</h3><small>${currentReview ? `已于 ${date(currentReview.createdAt, true)} 保存，只追加不覆盖` : reviewReady ? '前置步骤已完成；保存不等于执行交易' : `等待先完成：${escapeHtml(operation.current.label)}`}</small></div>${[['dataChecked','数据与决策链'],['holdingsChecked','持仓和现金'],['policyChecked','家庭资金边界'],['premiumChecked','QDII溢价'],['adviceChecked','建议与免交易带']].map(([name,label]) => `<label><input name="${name}" type="checkbox" ${currentReview?.[name as keyof typeof currentReview] === true ? 'checked disabled' : !reviewReady ? 'disabled' : ''}><span>${label}</span></label>`).join('')}<input name="reviewNote" type="text" maxlength="100" placeholder="家庭备注（可选）" ${currentReview || !reviewReady ? 'disabled' : ''}><button class="secondary" type="submit" ${currentReview || !reviewReady ? 'disabled' : ''}>${currentReview ? '本月已完成' : reviewReady ? '保存本月检查' : '完成前置步骤后可保存'}</button></form>`;
  return `<section class="page-intro reveal"><p>家庭人工执行</p><h1>持仓与建议</h1><p>先看本月结论，再对照真实持仓、家庭政策与整手计划。所有操作都需要家庭人工确认。</p><div class="page-links"><button class="primary" data-open-portfolio>${snapshot.health.blocking ? '仅保存本机持仓' : advice.available ? '更新本机账本' : '录入本机账本'}</button><a href="${context.root}allocation/index.html">查看目标形成依据</a></div></section>
    ${monthlyOperationMarkup(snapshot, portfolio, advice)}
    ${householdDecisionBrief(snapshot, advice, portfolio)}
    <section class="section first"><div class="metric-strip portfolio-scope reveal"><div><span>当前总资产</span><strong>${advice.available ? money(advice.recordedValue) : '待录入'}</strong><small>不含尚未发生的计划投入 · 更新：${updated}</small></div><div><span>当前持仓</span><strong>${advice.available ? percent(advice.currentEquity) : '未录入'}</strong><small>${equityCount}只权益 ETF 合计</small></div><div><span>模型确认目标</span><strong>${percent(advice.modelEquityTarget)}</strong><small>${snapshot.meta.confirmedSignalDate} 月末确认</small></div><div><span>家庭执行目标</span><strong>${percent(advice.operationalEquityTarget)}</strong><small>${policyActive ? `目标现金缓冲 ${percent(advice.targetCashWeight)}` : '家庭约束未启用'}</small></div></div>
      ${policyActive ? `<div class="policy-rail reveal"><div><span>模型权益目标</span><strong>${percent(advice.modelEquityTarget)}</strong></div><i>→</i><div><span>家庭约束后权益目标</span><strong>${percent(advice.operationalEquityTarget)}</strong></div><i>→</i><div><span>目标现金缓冲</span><strong>${percent(advice.targetCashWeight)}</strong></div></div>` : ''}
      ${householdPolicyMarkup(advice, portfolio)}
      <div class="section-head reveal"><div><p class="eyebrow">目标分解</p><h2>${snapshot.assets.length}只 ETF 的当前位置</h2></div><p>点击或按 Enter 选择资产，查看它在组合中的作用、信号和确认目标。</p></div>
      <div class="table-scroll table-edge asset-table-desktop"><table class="asset-table"><thead><tr><th>资产与角色</th><th>3个月</th><th>6个月</th><th>12个月</th><th>预测波动</th><th>相对强弱</th><th>当前</th><th>家庭执行目标</th><th>差额</th></tr></thead><tbody>${snapshot.assets.map((asset) => assetRow(asset, advice)).join('')}</tbody></table></div><aside id="asset-inspector" class="asset-inspector asset-table-desktop" aria-live="polite"></aside><div class="asset-mobile-list">${snapshot.assets.map((asset) => assetMobileRow(asset, advice)).join('')}</div>
    </section>
    <section id="monthly-advice" class="section"><div class="section-head reveal"><div><p class="eyebrow">人工执行建议</p><h2>现在需要行动吗</h2></div><p>只采用已完成月末目标，偏差必须越过免交易带；普通建议只修复 50% 缺口，并满足自融资约束。</p></div>
      <div class="advice-meta reveal"><span>决策频率 <strong>仅月末确认目标</strong></span><span>信号生效 <strong class="${advice.signalConfirmed && advice.signalEffective ? 'positive' : 'negative'}">${advice.signalConfirmed && advice.signalEffective ? `${snapshot.meta.confirmedEffectiveDate} 起可用` : '尚不可执行'}</strong></span><span>IPS Lite <strong class="${advice.policyStatus === 'CONFIRMED' ? 'positive' : 'warning'}">${policyStatusLabel(advice.policyStatus)}</strong></span><span>已确认可投资现金 <strong>${money(advice.contributionUsed)}</strong></span><span>估算交易成本 <strong>${money(advice.estimatedTransactionCost)}</strong></span><span>计划后现金 <strong class="${advice.cashAfterPlan < -1e-8 ? 'negative' : ''}">${money(advice.cashAfterPlan)}</strong></span><span>持仓时效 <strong class="${advice.holdingsFresh ? 'positive' : 'negative'}">${advice.holdingsFresh ? '有效' : '已过期'}</strong></span>${premiumMeta}<span>建议性质 <strong>人工复核，不执行交易</strong></span></div>${adviceMarkup(snapshot, advice)}
      ${advice.adviceAllowed ? `<div class="advice-record-action"><button class="secondary" data-record-advice ${currentAdviceSaved ? 'disabled' : ''}>${currentAdviceSaved ? '本期建议已留痕' : '保存本期建议到本机审计账本'}</button><small>保存不代表执行，不会连接券商或自动改变持仓。</small></div>` : ''}
    </section>
    <section id="execution-history" class="section compact"><div class="section-head reveal"><div><p>本机审计账本</p><h2>建议、成交、延期与现金流只追加留痕</h2></div><p>建议保存不代表执行；“已执行”必须有真实成交回报并通过现金与持仓对账。误录记录通过更正关系处理，不覆盖历史。</p></div>${monthlyChecklist}<div class="ledger-status"><span>资产基线 <strong>${portfolio.baseline?.date ?? '尚未建立'}</strong></span><span>有效快照 <strong>${activeSnapshots.length}</strong></span><span>建议 / 成交回报 <strong>${portfolio.adviceRecords?.length ?? 0} / ${portfolio.executionReports?.length ?? 0}</strong></span><span>QDII延期 <strong>${portfolio.qdiiDeferrals?.length ?? 0}</strong></span></div><details class="cash-flow-history"><summary>建议执行历史（${portfolio.adviceRecords?.length ?? 0}）</summary><div class="local-advice-history">${adviceHistory || '<p>尚未保存月末建议。</p>'}</div></details><details class="cash-flow-history"><summary>QDII 延期资金（${portfolio.qdiiDeferrals?.length ?? 0}）</summary>${deferrals ? `<ul class="deferral-list">${deferrals}</ul>` : '<p>尚无被门控的延期资金。</p>'}</details><details class="cash-flow-history"><summary>外部现金流（有效 ${cashFlows.length} / 全部 ${portfolio.cashFlows?.length ?? 0}）</summary>${flowRows ? `<div class="table-scroll"><table><thead><tr><th>录入日</th><th>估值生效日</th><th>类型</th><th>金额</th><th>说明</th><th>更正</th></tr></thead><tbody>${flowRows}</tbody></table></div>` : '<p>尚无已发生的外部现金流记录。</p>'}</details></section>
    <section class="section compact"><div class="section-head reveal"><div><p class="eyebrow">执行边界</p><h2>溢价门控不改风险模型</h2></div><p>${qdiiAssets.map((asset) => instrumentLabel(asset.code, asset.name)).join('、')}分别独立门控计划买入：1.5% 起减半，3% 起禁止新增，5% 起红色警告；门控不主动卖出，拦截资金临时转入国债ETF。</p></div>
      <div class="gate-scale" aria-label="QDII 溢价门控阈值"><span>正常<br><b>&lt; 1.5%</b></span><span>买入减半<br><b>1.5%—3%</b></span><span>禁止新增<br><b>3%—5%</b></span><span>红色警告<br><b>≥ 5%</b></span></div>
      ${advice.available ? '<button class="danger-link" data-clear-portfolio>清除本机持仓数据</button>' : ''}
    </section>`;
}

function renderModel(context: PageContext): string {
  if (!context.model) return '<section class="page-intro"><h1>风控模型</h1><p>模型文档载入失败。</p></section>';
  const toc = context.model.headings.filter((heading) => heading.level === 2).map((heading) => `<a href="#${heading.id}">${escapeHtml(heading.text.replace(/^\d+\.\s*/, ''))}</a>`).join('');
  return `<section class="page-intro model-intro reveal"><p class="eyebrow">MODEL MANUAL · 唯一文档源</p><h1>风险封控模型</h1><p>从数据异常到人工执行，逐层说明每个模型的公式、意义、约束和失效处理。页面内容由仓库 Markdown 原文生成。</p><div class="page-links"><a class="primary-link" href="${context.root}data/risk-control-models.md" download>下载 Markdown</a><a href="${context.root}data/index.html">查看当前数据验证</a></div></section>
    <section class="model-summary"><div><span>01</span><strong>数据健康</strong><p>输入不可信就阻断建议</p></div><div><span>02</span><strong>风险预算</strong><p>趋势、波动与回撤合成</p></div><div><span>03</span><strong>目标配置</strong><p>分组预算后有边界地配置ETF</p></div><div><span>04</span><strong>信号确认</strong><p>月末确认，人工目标最早 T+1 可用</p></div><div><span>05</span><strong>人工执行</strong><p>免交易带与部分再平衡</p></div></section>
    <section class="document-layout"><aside class="document-toc"><p>文档目录</p><nav aria-label="模型文档目录">${toc}</nav><a href="#main">返回顶部 ↑</a></aside><article class="markdown-body">${context.model.html}</article></section>`;
}

function backtestMarkup(snapshot: PublicSnapshot, root: string): string {
  if (snapshot.backtest.status !== 'OK') return '<p class="empty">回测尚未生成。</p>';
  const evidenceLabel = { LIMITED: '有限', MODERATE: '中等', STRONG: '较强' }[snapshot.backtest.robustness.evidenceLevel] ?? '有限';
  const walkForward = snapshot.backtest.robustness.walkForward ?? {
    testFolds: snapshot.backtest.robustness.walkForwardTestFolds,
    positiveCagrRate: null,
    worstCagr: null,
    medianMaxDrawdown: null,
  };
  const costStress = snapshot.backtest.robustness.costStress ?? [];
  const priorityRows = snapshot.backtest.strategies.map((strategy) => `<tr class="${strategy.key === 'D_FRAIS_V1' ? 'selected' : ''}"><td><strong>${escapeHtml(strategy.label)}</strong></td><td>${percent(strategy.metrics.maxDrawdown)}</td><td>${percent(strategy.metrics.worstYear)}</td><td>${percent(strategy.metrics.annualVolatility)}</td><td>${percent(strategy.metrics.turnover)}</td><td>${number(strategy.metrics.recoveryDays, 0)}</td><td>${percent(strategy.metrics.cagr)}</td></tr>`).join('');
  const fullRows = snapshot.backtest.strategies.map((strategy) => `<tr class="${strategy.key === 'D_FRAIS_V1' ? 'selected' : ''}"><td><strong>${escapeHtml(strategy.label)}</strong></td><td>${percent(strategy.metrics.cagr)}</td><td>${percent(strategy.metrics.annualVolatility)}</td><td>${percent(strategy.metrics.maxDrawdown)}</td><td>${number(strategy.metrics.sharpe)}</td><td>${number(strategy.metrics.sortino)}</td><td>${number(strategy.metrics.calmar)}</td><td>${percent(strategy.metrics.worstMonth)}</td><td>${percent(strategy.metrics.worstYear)}</td><td>${percent(strategy.metrics.rolling3YCagrMin)}</td><td>${percent(strategy.metrics.turnover)}</td><td>${number(strategy.metrics.tradeCount, 0)}</td><td>${number(strategy.metrics.recoveryDays, 0)}</td><td>${percent(strategy.metrics.timeUnderWater)}</td></tr>`).join('');
  const plots = snapshot.backtest.strategies.map((strategy) => `<article><span>${escapeHtml(strategy.label)}</span>${sparkline(strategy.nav, `${strategy.label}历史净值`)}</article>`).join('');
  const costRows = costStress.map((item) => `<tr><td><strong>${number(item.costBp, 0)} bp</strong></td><td>${item.cases}</td><td>${percent(item.medianCagr)}</td><td>${percent(item.medianMaxDrawdown)}</td><td>${percent(item.medianTurnover)}</td></tr>`).join('');
  return `<div class="metric-strip"><div><span>回测区间</span><strong class="small-value">${snapshot.backtest.period.start}<br>${snapshot.backtest.period.end}</strong></div><div><span>交易成本</span><strong>${percent(snapshot.backtest.costRate, 2)}</strong><small>敏感性含 5 / 10 / 20bp</small></div><div><span>参数组合</span><strong>${snapshot.backtest.robustness.cases}</strong><small>不搜索最优单点</small></div><div><span>当前样本稳定性</span><strong class="${snapshot.backtest.robustness.warning ? 'warning' : 'positive'}">${snapshot.backtest.robustness.warning ? '过拟合警告' : '通过'}</strong><small>通过率 ${percent(snapshot.backtest.robustness.passRate)} · 证据${evidenceLabel}</small></div></div>
    <div class="evidence-grade"><strong>当前样本内参数区域：${snapshot.backtest.robustness.warning ? '存在脆弱性警告' : '相对稳定'}</strong><span>跨周期证据：${evidenceLabel} · 时序样本外分段 ${walkForward.testFolds} 个</span><p>这不是“策略已经跨周期验证”的结论，也不保证未来有效。当前公开样本较短，只支持低换手风险折中的有限判断。优化优先级：${snapshot.policy.priority.map(escapeHtml).join(' ＞ ')}。</p></div>
    <div class="validation-ledger"><div><span>样本外正 CAGR 分段</span><strong>${percent(walkForward.positiveCagrRate)}</strong><small>${walkForward.testFolds} 个测试分段</small></div><div><span>样本外最差 CAGR</span><strong>${percent(walkForward.worstCagr)}</strong><small>观察脆弱区间，不追求峰值</small></div><div><span>样本外中位最大回撤</span><strong>${percent(walkForward.medianMaxDrawdown)}</strong><small>优先审查风险控制</small></div></div>
    ${costRows ? `<div class="cost-stress"><div><p class="eyebrow">TRANSACTION COST STRESS</p><h3>成本升高后是否仍有解释力</h3><p>展示每个成本情景下全部参数组合的中位结果，不挑选收益最高的单点。</p></div><div class="table-scroll"><table><thead><tr><th>单边成本</th><th>参数组合</th><th>中位 CAGR</th><th>中位最大回撤</th><th>中位年换手</th></tr></thead><tbody>${costRows}</tbody></table></div></div>` : ''}
    <div class="benchmark-questions reveal"><div><b>A</b><strong>战略锚本身如何表现</strong><span>年度再平衡的固定配置</span></div><div><b>B</b><strong>只控制偏离是否足够</strong><span>固定配置 + 5/25阈值</span></div><div><b>C</b><strong>单一趋势过滤有何代价</strong><span>200日均线风险过滤</span></div><div><b>D</b><strong>多因子风险预算是否更平衡</strong><span>资产 V5 · FRAIS 1.2 七资产核心—卫星配置，不按 CAGR 选胜者</span></div></div>
    <div class="nav-compare">${plots}</div>
    <div class="table-scroll table-edge"><table class="metrics-table priority-metrics"><thead><tr><th>策略</th><th>最大回撤</th><th>最差年</th><th>年化波动</th><th>年换手</th><th>恢复天数</th><th>CAGR</th></tr></thead><tbody>${priorityRows}</tbody></table></div>
    <details class="metrics-details"><summary>查看全部 14 项回测指标</summary><div class="table-scroll"><table class="metrics-table"><thead><tr><th>策略</th><th>CAGR</th><th>年化波动</th><th>最大回撤</th><th>Sharpe</th><th>Sortino</th><th>Calmar</th><th>最差月</th><th>最差年</th><th>滚动3年最低CAGR</th><th>年换手</th><th>交易次数</th><th>恢复天数</th><th>水下时间</th></tr></thead><tbody>${fullRows}</tbody></table></div></details>
    <p class="method-note">无风险利率按0处理；公开回测未包含历史逐时点513500 标普500ETF与513100 纳指ETF溢价门控。系统不按历史收益最高选择参数。完整结果可<a href="${root}data/parameter-sensitivity.csv" download>下载参数敏感性 CSV</a>，模型历史可<a href="${root}data/decision-log.json" download>下载决策审计日志</a>。</p>`;
}

function renderData(context: PageContext): string {
  const { snapshot, root } = context;
  const downloadRoot = snapshot.meta.buildId ? `${root}data/releases/${snapshot.meta.buildId}/` : `${root}data/`;
  const performance = context.performance;
  const timingAudit = snapshot.timingAudit ?? {
    status: '待重新发布', signalAtClose: true, positionShiftTradingDays: 1,
    monthEndOnly: true, adjustedPriceOnly: true, premiumGateSeparated: true,
  };
  const effectiveDate = snapshot.meta.confirmedEffectiveDate ?? '下一交易日';
  const commonStart = Object.values(snapshot.provenance).map((source) => source.firstDate).filter(Boolean).sort().at(-1) ?? '—';
  const commonEnd = Object.values(snapshot.provenance).map((source) => source.lastDate).filter(Boolean).sort().at(0) ?? '—';
  const providerRows = Object.entries(snapshot.provenance).map(([code, source]) => `<tr><td><strong>${escapeHtml(labelForCode(snapshot, code))}</strong></td><td>${escapeHtml(source.source)}</td><td>${escapeHtml(source.firstDate ?? '—')}</td><td>${escapeHtml(source.lastDate ?? '—')}</td><td>${escapeHtml(source.observations ?? '—')}</td><td>${source.durationMs == null ? '历史快照' : `${number(source.durationMs / 1000, 1)} 秒`}</td><td>${source.calendarFillCount ? `${source.calendarFillCount} · ${escapeHtml(source.calendarFilledDates?.join('、') ?? '')}` : '0'}</td></tr>`).join('');
  const decisionIntegrity = snapshot.decisionIntegrity;
  const timingChecks = [
    ['收盘后计算', timingAudit.signalAtClose, '只使用 Close T 已知数据'],
    ['人工 / 回测时序', timingAudit.positionShiftTradingDays === 1, `人工目标 ${effectiveDate} 起可用；close-only 回测在 T+1 收盘成交，新仓从 T+2 收益起计`],
    ['月末确认', timingAudit.monthEndOnly, '日频结果只观察'],
    ['复权价格', timingAudit.adjustedPriceOnly, '趋势与回测口径一致'],
    ['估值价分离', timingAudit.valuationPriceSeparated === true, '份额估值使用原始收盘价，不使用复权序列冒充真实价格'],
    ['溢价门控分离', timingAudit.premiumGateSeparated, '不反向污染风险模型'],
  ].map(([label, passed, detail]) => `<div><span>${label}</span><strong class="${passed ? 'positive' : 'negative'}">${passed ? '通过' : '失败'}</strong><small>${detail}</small></div>`).join('');
  const issueMarkup = snapshot.health.issues.length ? `<div class="issue-list">${snapshot.health.issues.map((issue) => `<p><strong>${escapeHtml(issue.label)}</strong><span>${escapeHtml(labelForCode(snapshot, issue.code))} · ${escapeHtml(issue.details)}</span></p>`).join('')}</div>` : '<p class="health-pass">Missing Date、Duplicate Date、Zero / Negative Price、Abnormal Jump、Stale Data 与 Provider Error 均未发现阻断问题。</p>';
  const triage = snapshot.health.blocking
    ? ['停止形成新建议', '查看下方首个 ERROR 与受影响标的', '等待完整数据包重新发布；不要用旧错误覆盖新快照']
    : ['确认 DATA OK 与生成时间', '确认决策链、时序审计和模型审计均通过', '再查看月末目标；日频和周频只作观察'];
  const observations = context.publicationObservations ?? [];
  const successfulStreak = observations.findIndex((item) => item.blocking);
  const visibleStreak = successfulStreak < 0 ? observations.length : successfulStreak;
  const failures = observations.filter((item) => item.blocking);
  const latestGood = observations.find((item) => !item.blocking);
  const previousGood = observations.filter((item) => !item.blocking && item.buildId !== latestGood?.buildId).at(0);
  const latestFailure = failures.at(0);
  const dataLagHours = Math.max(0, (Date.now() - new Date(snapshot.meta.generatedAt).getTime()) / 3_600_000);
  const observationRows = observations.slice(0, 6).map((item) => `<li><i class="${item.blocking ? 'failed' : 'passed'}"></i><span><strong>${escapeHtml(item.blocking ? '阻断观察' : '完整数据包')}</strong><small>${date(item.observedAt, true)} · ${escapeHtml(item.source)}</small></span><code>${escapeHtml(item.buildId.slice(0, 28))}…</code><em>${escapeHtml(item.summary)}</em></li>`).join('');
  return `<section class="page-intro reveal"><p class="eyebrow">LAYER 01 · DATA & AUDIT</p><h1>数据与验证</h1><p>先证明输入与时序可信，再讨论历史表现。所有公开结果都可以下载复核，私人持仓不会进入这些文件。</p></section>
    <section class="health-banner ${snapshot.health.blocking ? 'blocked' : ''}"><div><span>${snapshot.health.blocking ? 'DATA ERROR' : 'DATA OK'}</span><strong>${snapshot.health.blocking ? '新建议闸门关闭' : '新建议闸门开放'}</strong></div><p>${escapeHtml(snapshot.health.summary)}</p><small>生成于 ${date(snapshot.meta.generatedAt, true)}</small></section>
    <section class="data-triage"><div><p class="eyebrow">先做什么</p><h2>${snapshot.health.blocking ? '错误优先，停止判断' : '三步确认本批数据可信'}</h2></div><ol>${triage.map((item, index) => `<li><b>0${index + 1}</b><span>${escapeHtml(item)}</span></li>`).join('')}</ol><aside><span>发布批次</span><strong>${escapeHtml(snapshot.meta.buildId ?? 'V5.0 兼容模式')}</strong><small>同一批次的快照、健康和行情才允许一起使用</small></aside></section>
    <section class="publication-reliability reveal"><div class="publication-reliability-lead"><p class="eyebrow">PUBLICATION RELIABILITY · 当前浏览器</p><h2>${snapshot.health.blocking ? '当前建议不可信，保持只读' : '当前数据包可以用于月末人工复核'}</h2><p>这里记录本浏览器实际见过的发布状态，不把有限观察冒充完整生产历史。</p><dl><div><dt>连续正常观察</dt><dd>${visibleStreak} 次</dd></div><div><dt>阻断观察</dt><dd>${failures.length} 次</dd></div><div><dt>数据包年龄</dt><dd>${number(dataLagHours, 1)} 小时</dd></div><div><dt>上一有效批次</dt><dd>${escapeHtml(previousGood?.buildId.slice(0, 16) ?? '尚未观察')}</dd></div></dl>${latestFailure ? `<small class="warning">最近阻断：${escapeHtml(latestFailure.summary)}</small>` : '<small class="positive">当前浏览器尚未观察到发布阻断</small>'}<small>当前有效源码 ${escapeHtml(latestGood?.sourceCommit.slice(0, 12) ?? snapshot.meta.sourceCommit?.slice(0, 12) ?? '—')}</small></div><ol class="publication-observations">${observationRows || '<li><span><strong>等待首次观察</strong><small>刷新后记录当前数据包</small></span></li>'}</ol></section>
    <section class="section first"><div class="section-head reveal"><div><p class="eyebrow">数据健康</p><h2>先看输入，再看结论</h2></div><p>${snapshot.assets.length}只 ETF 使用前复权收盘价，并在共同交易日历上对齐。孤立停牌日只有留下审计记录后才允许填充。</p></div>
      <div class="audit-strip"><div><span>共同可用区间</span><strong>${commonStart} → ${commonEnd}</strong></div><div><span>价格约定</span><strong>${escapeHtml(snapshot.meta.priceConvention)}</strong></div><div><span>决策链</span><strong class="${decisionIntegrity?.status === 'PASS' ? 'positive' : 'warning'}">${decisionIntegrity?.status ?? '待升级'}</strong><small>${decisionIntegrity ? `${decisionIntegrity.entries} 条 · ${decisionIntegrity.latestHash.slice(0, 12)}…` : '旧日志尚无哈希链'}</small></div><div><span>确认信号 → 首个可用日</span><strong>${snapshot.meta.confirmedSignalDate} → ${effectiveDate}</strong></div></div>${modelIntegrityMarkup(snapshot)}${issueMarkup}
      <div class="timing-ledger" aria-label="未来函数审计">${timingChecks}</div>
      <p class="method-note">时序审计状态：<strong class="${timingAudit.status === 'PASS' ? 'positive' : 'warning'}">${escapeHtml(timingAudit.status)}</strong>。行情抓取可并发进行，但任一 ETF 获取失败仍会阻断整批数据与新建议。</p>
      <div class="table-scroll table-edge"><table class="provider-table"><thead><tr><th>ETF</th><th>来源</th><th>首日</th><th>末日</th><th>原始观测</th><th>获取耗时</th><th>审计填充</th></tr></thead><tbody>${providerRows}</tbody></table></div>
    </section>
    <section class="section"><div class="section-head reveal"><div><p class="eyebrow">独立验证 · CLOSE-ONLY</p><h2>回测与参数稳健性</h2></div><p>A / B / C / D 统一使用复权收盘价和显式成本。T 收盘信号在 T+1 收盘成交，新仓位从 T+2 的收益开始计入；这与人工目标最早 T+1 可用是两个口径。比较只用来理解风险—收益—换手权衡。</p></div>${backtestMarkup(snapshot, root)}</section>
    <section class="section compact"><div class="section-head reveal"><div><p class="eyebrow">家庭资产记录质量 · 仅本机</p><h2>收益结论是否足够可信</h2></div><p>这组数字只在浏览器内计算，不写入公开快照、下载文件或GitHub日志。</p></div><div class="local-quality-grid"><div><span>首次记录</span><strong>${performance?.baselineDate ?? '尚未建立'}</strong></div><div><span>最近确认</span><strong>${context.portfolio.updatedAt === new Date(0).toISOString() ? '尚未录入' : date(context.portfolio.updatedAt, true)}</strong></div><div><span>有效快照 / 现金流</span><strong>${(context.portfolio.snapshots ?? []).filter((item) => !item.supersededBy).length} / ${activeCashFlows(context.portfolio).length}</strong></div><div><span>收益质量</span><strong class="${performance?.quality === 'CONFIRMED' ? 'positive' : 'warning'}">${performance?.qualityLabel ?? '需在资产总览载入估值序列'}</strong></div><div><span>家庭当前 / 最大回撤</span><strong>${percent(performance?.currentDrawdown)} / ${percent(performance?.maxDrawdown)}</strong></div><div><span>水下交易日</span><strong>${performance?.underwaterTradingDays == null ? '—' : `${performance.underwaterTradingDays} 日`}</strong></div><div><span>份额确认覆盖率</span><strong>${percent(performance?.confirmedQuantityCoverage)}</strong></div><div><span>旧数据迁移</span><strong>${context.portfolio.migration?.status === 'MIGRATED_PENDING_CONFIRMATION' ? '待用户确认' : context.portfolio.migration?.status === 'ERROR' ? '迁移错误' : '正常'}</strong></div><div><span>隐私边界</span><strong>仅当前浏览器</strong></div></div></section>
    <section class="section compact"><div class="section-head reveal"><div><p class="eyebrow">公开文件</p><h2>下载并复核</h2></div><p>这些文件只包含公开行情和模型输出。浏览器本机持仓、现金、溢价与备份密码不会被打包。</p></div>
      <div class="download-list"><a href="${downloadRoot}snapshot.json" download><span>JSON</span><strong>风险与目标快照</strong><small>页面使用的数据契约</small></a><a href="${downloadRoot}health.json" download><span>JSON</span><strong>同批健康检查</strong><small>与快照共享 buildId</small></a><a href="${downloadRoot}decision-log.json" download><span>JSON</span><strong>月末决策审计</strong><small>历史目标不覆盖</small></a><a href="${downloadRoot}market-series.json" download><span>JSON</span><strong>真实日线与成交量</strong><small>${snapshot.assets.length}只 ETF 前复权 OHLCV + 原始估值收盘价</small></a><a href="${downloadRoot}adjusted-prices.csv" download><span>CSV</span><strong>前复权价格</strong><small>${snapshot.assets.length}只 ETF 公共日历</small></a><a href="${downloadRoot}parameter-sensitivity.csv" download><span>CSV</span><strong>参数敏感性</strong><small>81 组参数区域</small></a><a href="${downloadRoot}risk-control-models.md" download><span>MD</span><strong>风控模型文档</strong><small>公式、边界与失效处理</small></a></div>
    </section>`;
}

export function renderPage(context: PageContext): string {
  if (context.page === 'model') return renderModel(context);
  if (context.page === 'data') return renderData(context);
  const banner = dataErrorBanner(context);
  if (context.page === 'market') return `${banner}${renderMarket(context)}`;
  if (context.page === 'allocation') return `${banner}${renderAllocation(context)}`;
  if (context.page === 'portfolio') return `${banner}${renderPortfolio(context)}`;
  return `${banner}${renderOverview(context)}`;
}
