import { escapeHtml, instrumentLabel } from './format';
import { activeCashFlows } from './portfolio-ledger';
import type { LocalPortfolio, PublicSnapshot } from './types';

export function portfolioDialog(snapshot: PublicSnapshot, portfolio: LocalPortfolio): string {
  const policy = portfolio.ipsPolicy;
  const buckets = portfolio.fundBuckets;
  const qdiiAssets = snapshot.assets.filter((asset) => asset.qdii || snapshot.executionModel.qdiiCodes?.includes(asset.code));
  const snapshots = (portfolio.snapshots ?? []).filter((item) => !item.supersededBy);
  const positionFields = snapshot.assets.map((asset) => {
    const position = portfolio.positionsByCode?.[asset.code];
    const mode = position?.inputMode ?? 'MARKET_VALUE';
    const amount = mode === 'QUANTITY' ? position?.quantity : position?.confirmedMarketValue ?? portfolio.values[asset.code];
    const valuation = asset.valuationClose ? `¥${asset.valuationClose.toFixed(3)}` : '缺失';
    return `<label><span>${escapeHtml(instrumentLabel(asset.code, asset.name))}<small>${escapeHtml(asset.role)} · 未复权估值价 ${valuation}（${escapeHtml(asset.valuationPriceDate ?? '—')}）</small></span><span class="position-input"><select name="mode-${asset.code}" aria-label="${escapeHtml(asset.name)}输入方式"><option value="QUANTITY" ${mode === 'QUANTITY' ? 'selected' : ''}>份额</option><option value="MARKET_VALUE" ${mode === 'MARKET_VALUE' ? 'selected' : ''}>市值</option></select><input name="${asset.code}" type="number" min="0" step="0.01" inputmode="decimal" value="${amount || ''}" placeholder="0.00"></span></label>`;
  }).join('');
  const inputValue = (value: number | null | undefined, scale = 1) => value == null ? '' : value * scale;
  const policyStatus = ({ UNSET: '未建立', DRAFT: '待确认', CONFIRMED: '已确认', DUE: '待复核', EXPIRED: '已失效' } as Record<string, string>)[policy?.status ?? 'UNSET'];
  const executionFields = snapshot.assets.map((asset) => `<div class="execution-fill" data-execution-code="${asset.code}"><span><strong>${escapeHtml(instrumentLabel(asset.code, asset.name))}</strong><small>建议份额将在打开时带入；请以真实成交为准</small></span><select name="fill-side-${asset.code}" aria-label="${asset.name}方向"><option value="BUY">买入</option><option value="SELL">卖出</option></select><input name="fill-shares-${asset.code}" type="number" min="0" step="1" inputmode="numeric" placeholder="成交份额"><input name="fill-price-${asset.code}" type="number" min="0" step="0.001" inputmode="decimal" value="${asset.valuationClose ?? ''}" placeholder="成交价"><input name="fill-fee-${asset.code}" type="number" min="0" step="0.01" inputmode="decimal" placeholder="费用"></div>`).join('');
  return `<dialog id="portfolio-dialog"><form method="dialog" id="portfolio-form"><div class="dialog-head"><div><p>仅当前浏览器</p><h2>本机家庭账本</h2></div><button type="button" data-close-dialog aria-label="关闭">×</button></div><p class="privacy">推荐填写实际份额，系统只用未复权收盘价估值。保存会追加本机快照；首次确认才建立资产基线，不反推过去收益。</p>
    <nav class="dialog-step-nav" aria-label="账本录入步骤"><button type="button" class="active" data-ledger-step-button="holdings">1 持仓</button><button type="button" data-ledger-step-button="policy">2 家庭边界</button><button type="button" data-ledger-step-button="cashflow">3 现金流</button><button type="button" data-ledger-step-button="backup">4 备份</button></nav>
    <div class="record-summary"><span>资产基线 <strong>${portfolio.baseline?.date ?? '尚未建立'}</strong></span><span>有效快照 <strong>${snapshots.length}</strong></span><span>投资政策 <strong>${policyStatus}</strong></span></div>
    <section class="dialog-section dialog-step active" data-ledger-step="holdings"><h3>持仓与组合内现金</h3><div class="holding-fields">${positionFields}
      <label><span>组合内现金<small>计入总资产；只有已确认可投资部分用于新增买入</small></span><input name="cash" type="number" min="0" step="0.01" inputmode="decimal" value="${portfolio.cash || ''}" placeholder="0.00"></label>
      ${qdiiAssets.map((asset) => `<label><span>${escapeHtml(instrumentLabel(asset.code, asset.name))} 当前溢价<small>输入百分数，例如 2.1；各自独立门控</small></span><input name="premium-${asset.code}" type="number" step="0.01" inputmode="decimal" value="${portfolio.qdiiPremiums?.[asset.code] == null ? '' : Number(portfolio.qdiiPremiums[asset.code]) * 100}" placeholder="缺失或过期时阻断该标的新增买入"></label>`).join('')}</div></section>
    <details class="dialog-disclosure dialog-step" data-ledger-step="policy" open><summary><span><strong>家庭投资政策与资金边界</strong><small>未确认时仍可查看模型，但只允许复核降低风险</small></span><b>${policyStatus}</b></summary><fieldset class="policy-fields"><legend>IPS Lite · 家庭自行制定，不是适当性推荐</legend><label class="policy-toggle"><input name="policyEnabled" type="checkbox" ${policy?.enabled ? 'checked' : ''}><span>启用家庭政策<small>只能降低模型风险，不会提高权益目标</small></span></label><div class="holding-fields">
      <label><span>管理范围</span><input name="managedScope" type="text" maxlength="80" value="${escapeHtml(policy?.managedScope ?? '七只ETF与组合内现金')}"></label>
      <label><span>应急备用金<small>必须在本组合之外单独留足</small></span><select name="emergencyFundReady"><option value="" ${policy?.emergencyFundReady == null ? 'selected' : ''}>未确认</option><option value="yes" ${policy?.emergencyFundReady === true ? 'selected' : ''}>已隔离并准备完成</option><option value="no" ${policy?.emergencyFundReady === false ? 'selected' : ''}>尚未准备</option></select></label>
      <label><span>未来12个月确定支出</span><input name="needs12" type="number" min="0" step="0.01" value="${inputValue(buckets?.nearTermNeeds12Months)}" placeholder="0.00"></label>
      <label><span>13—36个月确定支出</span><input name="needs36" type="number" min="0" step="0.01" value="${inputValue(buckets?.nearTermNeeds13To36Months)}" placeholder="0.00"></label>
      <label><span>37—60个月确定支出</span><input name="needs60" type="number" min="0" step="0.01" value="${inputValue(buckets?.nearTermNeeds37To60Months)}" placeholder="0.00"></label>
      <label><span>组合内可投资现金<small>不得超过上方组合内现金</small></span><input name="investableCash" type="number" min="0" step="0.01" value="${inputValue(buckets?.investableCash)}" placeholder="0.00"></label>
      <label><span>家庭权益上限</span><input name="householdEquityCap" type="number" min="0" max="100" step="0.1" value="${inputValue(policy?.householdEquityCap, 100)}" placeholder="例如 70"></label>
      <label><span>近期负债约束上限<small>可留空</small></span><input name="liabilityEquityCap" type="number" min="0" max="100" step="0.1" value="${inputValue(policy?.liabilityEquityCap, 100)}"></label>
      <label><span>投资期限（年）</span><input name="horizonYears" type="number" min="1" max="100" step="1" value="${inputValue(policy?.horizonYears)}" placeholder="例如 20"></label>
      <label><span>最大可承受账面损失</span><input name="maxTolerableDrawdown" type="number" min="0" max="100" step="0.1" value="${inputValue(policy?.maxTolerableDrawdown, 100)}" placeholder="例如 25"></label>
      <label><span>持续投入稳定性</span><select name="contributionStability"><option value="UNSET" ${policy?.contributionStability === 'UNSET' ? 'selected' : ''}>未确认</option><option value="LOW" ${policy?.contributionStability === 'LOW' ? 'selected' : ''}>较低</option><option value="MEDIUM" ${policy?.contributionStability === 'MEDIUM' ? 'selected' : ''}>一般</option><option value="HIGH" ${policy?.contributionStability === 'HIGH' ? 'selected' : ''}>较高</option></select></label>
      <label><span>确认人标签<small>例如“家庭共同确认”，不填写真实身份</small></span><input name="confirmedBy" type="text" maxlength="40" value="${escapeHtml(policy?.confirmedBy ?? '')}"></label>
      <label><span>下次复核日</span><input name="reviewDueDate" type="date" value="${policy?.reviewDueDate ?? ''}"></label>
      <label><span>政策失效日</span><input name="policyExpiresAt" type="date" value="${policy?.expiresAt ?? ''}"></label>
    </div><label class="policy-confirm"><input name="policyConfirm" type="checkbox"><span>我确认以上边界由家庭自行制定，排除资金不会进入本组合，本次保存后作为新的正式政策版本。</span></label></fieldset></details>
    <details class="dialog-disclosure dialog-step" data-ledger-step="cashflow" open><summary><span><strong>现金流、计划投入与更正</strong><small>外部转入转出用于现金流中性收益；非交易日自动映射到下一估值日</small></span></summary><fieldset class="cash-flow-fields"><legend>本次是否包含已经发生的外部现金流</legend><p>ETF之间买卖属于组合内部调整，不要填写。</p><div><select name="cashFlowType"><option value="">无现金流</option><option value="CONTRIBUTION">新增资金</option><option value="WITHDRAWAL">取出资金</option></select><input name="cashFlowDate" type="date" value="${new Date().toISOString().slice(0, 10)}"><input name="cashFlowAmount" type="number" min="0" step="0.01" placeholder="金额"><input name="cashFlowNote" type="text" maxlength="80" placeholder="说明（可选）"></div><label><span>未来计划投入<small>只作家庭记录，不进入当前总资产或本期买入预算</small></span><input name="monthlyContribution" type="number" min="0" step="0.01" value="${portfolio.plannedMonthlyContribution || ''}" placeholder="0.00"></label></fieldset></details>
    <details class="dialog-disclosure dialog-step" data-ledger-step="backup" open><summary><span><strong>加密备份与恢复</strong><small>导入先预览，覆盖前自动保存本机恢复点</small></span></summary><div class="backup"><div><h3>完整账本加密备份</h3><p>导出前会执行一次加密—解密干跑校验；密码不会保存，忘记后无法恢复。</p><small>备份健康：${portfolio.backupHealth?.status ?? 'UNTESTED'} · ${escapeHtml(portfolio.backupHealth?.message ?? '尚未校验')}</small><small>最近恢复点：${portfolio.backupHealth?.lastRecoveryPointAt?.slice(0, 10) ?? '尚未建立'} · 最近恢复：${portfolio.backupHealth?.lastRestoredAt?.slice(0, 10) ?? '尚未执行'}</small></div><input class="visually-hidden" type="text" autocomplete="username" value="资产 本机备份" tabindex="-1" aria-hidden="true"><input id="backup-password" type="password" minlength="8" autocomplete="new-password" placeholder="备份密码，至少 8 个字符"><div class="backup-actions"><button type="button" class="secondary" id="export-backup">校验并导出</button><button type="button" class="secondary" id="import-backup">选择文件并预览</button>${portfolio.backupHealth?.lastRecoveryPointId ? '<button type="button" class="text-button" id="restore-recovery-point">预览导入前恢复点</button>' : ''}<input id="backup-file" type="file" accept="application/json,.json" hidden></div></div></details>
    <div id="dialog-status" class="dialog-status" aria-live="polite"></div><div class="dialog-actions"><button type="button" data-close-dialog class="secondary">取消</button><button type="submit" class="primary">${snapshot.health.blocking ? '仅保存本机资产记录' : '保存并重新计算'}</button></div></form></dialog>
    <dialog id="execution-dialog"><form method="dialog" id="execution-form"><div class="dialog-head"><div><p>真实成交回报 · 仅当前浏览器</p><h2>成交与现金对账</h2></div><button type="button" data-close-execution aria-label="关闭">×</button></div><p class="privacy">这不是交易入口。请在券商完成操作后抄录真实成交；只有现金与持仓对账通过，建议才能标记为部分执行或已执行。</p><input name="executionAdviceId" type="hidden"><input name="executionStatus" type="hidden"><div class="execution-meta"><label><span>成交日期</span><input name="executionTradeDate" type="date" value="${new Date().toISOString().slice(0, 10)}" required></label><label><span>成交后组合内现金</span><input name="executionCashAfter" type="number" min="0" step="0.01" required></label></div><div class="execution-fill-head"><span>标的</span><span>方向</span><span>真实份额</span><span>真实成交价</span><span>费用</span></div>${executionFields}<label class="execution-note"><span>执行说明</span><input name="executionNote" type="text" maxlength="120" placeholder="可选；例如分批成交原因"></label><div id="execution-status" class="dialog-status" aria-live="polite"></div><div class="dialog-actions"><button type="button" data-close-execution class="secondary">取消</button><button type="submit" class="primary">校验并保存成交回报</button></div></form></dialog>
    <dialog id="restore-preview-dialog"><div class="dialog-head"><div><p>导入前预览 · 不会立即覆盖</p><h2>核对要恢复的家庭账本</h2></div><button type="button" data-cancel-restore aria-label="关闭">×</button></div><p class="privacy">确认后，系统会先把当前账本保存为独立恢复点，再导入所选备份。恢复点只保存在当前浏览器。</p><div id="restore-preview-summary" class="restore-preview-summary" aria-live="polite"></div><div class="dialog-actions"><button type="button" data-cancel-restore class="secondary">取消</button><button type="button" id="confirm-restore" class="primary">建立恢复点并导入</button></div></dialog>`;
}
