import { latestAdviceStatus } from './portfolio-ledger';
import type { AdviceResult } from './rebalance';
import type { AssetCode, LocalAdviceRecord, LocalPortfolio, PublicSnapshot } from './types';

export type HouseholdOperationAction = 'NONE' | 'OPEN_HOLDINGS' | 'OPEN_POLICY' | 'OPEN_PREMIUM' | 'REVIEW_ADVICE' | 'RECORD_EXECUTION' | 'COMPLETE_REVIEW';
export type HouseholdOperationStatus = 'DONE' | 'CURRENT' | 'WAITING' | 'BLOCKED';

export interface HouseholdOperationStep {
  key: 'DATA' | 'HOLDINGS' | 'POLICY' | 'PREMIUM' | 'ADVICE' | 'EXECUTION' | 'REVIEW';
  label: string;
  detail: string;
  status: HouseholdOperationStatus;
  action: HouseholdOperationAction;
}

export interface HouseholdOperationState {
  month: string;
  completed: number;
  total: number;
  steps: HouseholdOperationStep[];
  current: HouseholdOperationStep;
  adviceRecord?: LocalAdviceRecord;
}

function latestActiveSnapshotId(portfolio: LocalPortfolio): string | null {
  return [...(portfolio.snapshots ?? [])]
    .filter((item) => !item.supersededBy)
    .sort((left, right) => left.createdAt.localeCompare(right.createdAt))
    .at(-1)?.id ?? null;
}

export function deriveHouseholdOperation(
  snapshot: PublicSnapshot,
  portfolio: LocalPortfolio,
  advice: AdviceResult,
): HouseholdOperationState {
  const month = snapshot.meta.confirmedSignalDate.slice(0, 7);
  const activeRows = advice.rows.filter((row) => row.action !== 'NO TRADE');
  const snapshotId = latestActiveSnapshotId(portfolio);
  const adviceRecord = [...(portfolio.adviceRecords ?? [])].reverse().find((record) => (
    record.signalDate === snapshot.meta.confirmedSignalDate && record.holdingsSnapshotId === snapshotId
  ));
  const adviceStatus = adviceRecord
    ? latestAdviceStatus(portfolio, adviceRecord.adviceId)?.status ?? adviceRecord.status
    : undefined;
  const executionDone = activeRows.length === 0
    || adviceStatus === 'EXECUTED'
    || adviceStatus === 'SKIPPED'
    || adviceStatus === 'EXPIRED';
  const completedReview = (portfolio.monthlyReviews ?? []).some((review) => review.month === month);
  const definitions: Array<Omit<HouseholdOperationStep, 'status'> & { done: boolean }> = [
    {
      key: 'DATA', label: '核对数据与决策链', action: 'NONE',
      detail: snapshot.health.blocking ? snapshot.health.summary : `${snapshot.meta.signalDate} 数据健康，月末信号 ${snapshot.meta.confirmedSignalDate} 已确认`,
      done: !snapshot.health.blocking,
    },
    {
      key: 'HOLDINGS', label: '更新真实持仓与现金', action: 'OPEN_HOLDINGS',
      detail: !advice.available ? '尚未建立资产基线' : advice.holdingsFresh ? `本机持仓更新于 ${portfolio.updatedAt.slice(0, 10)}` : '持仓已过期，暂停形成新建议',
      done: advice.available && advice.holdingsFresh,
    },
    {
      key: 'POLICY', label: '确认家庭资金边界', action: 'OPEN_POLICY',
      detail: advice.policyStatus === 'CONFIRMED' && advice.riskIncreaseAllowed ? 'IPS Lite 已确认，家庭约束只降低风险' : advice.riskIncreaseBlockedReason ?? '家庭政策尚未确认',
      done: advice.policyStatus === 'CONFIRMED' && advice.riskIncreaseAllowed,
    },
    {
      key: 'PREMIUM', label: '核对 QDII 溢价', action: 'OPEN_PREMIUM',
      detail: advice.premiumFresh ? '双 QDII 溢价均在有效期内' : '溢价缺失或过期，对应新增买入会被阻断',
      done: advice.premiumFresh,
    },
    {
      key: 'ADVICE', label: activeRows.length ? '保存本期人工建议' : '确认本期无需调仓', action: 'REVIEW_ADVICE',
      detail: activeRows.length ? `${activeRows.length}只 ETF 越过执行边界${adviceRecord ? '，建议已只追加留痕' : '，等待家庭复核并保存'}` : '全部资产均在免交易带内',
      done: activeRows.length === 0 || Boolean(adviceRecord),
    },
    {
      key: 'EXECUTION', label: activeRows.length ? '登记成交或跳过决定' : '无需登记成交', action: 'RECORD_EXECUTION',
      detail: activeRows.length === 0 ? '本期没有执行动作' : adviceStatus ? `当前状态：${adviceStatus}` : '保存建议后才能登记真实成交',
      done: executionDone,
    },
    {
      key: 'REVIEW', label: '完成家庭月度复盘', action: 'COMPLETE_REVIEW',
      detail: completedReview ? '本月检查单已保存，只追加不覆盖' : '确认数据、持仓、政策、溢价和执行结论',
      done: completedReview,
    },
  ];
  let waiting = false;
  const steps = definitions.map((definition): HouseholdOperationStep => {
    let status: HouseholdOperationStatus;
    if (definition.done) status = 'DONE';
    else if (!waiting) {
      status = definition.key === 'DATA' && snapshot.health.blocking ? 'BLOCKED' : 'CURRENT';
      waiting = true;
    } else status = 'WAITING';
    return { ...definition, status };
  });
  const current = steps.find((step) => step.status === 'CURRENT' || step.status === 'BLOCKED') ?? {
    key: 'REVIEW', label: '本月流程已完成', detail: '维持组合并等待下一次月末确认', status: 'DONE', action: 'NONE',
  };
  return { month, completed: steps.filter((step) => step.status === 'DONE').length, total: steps.length, steps, current, adviceRecord };
}

export interface ExecutionVarianceRow {
  code: AssetCode;
  plannedAmount: number;
  actualAmount: number;
  difference: number;
  actualFee: number;
}

export interface ExecutionVarianceSummary {
  available: boolean;
  plannedNotional: number;
  actualNotional: number;
  completionRate: number | null;
  plannedFees: number;
  actualFees: number;
  feeDifference: number;
  maximumTargetDeviation: number | null;
  rows: ExecutionVarianceRow[];
}

export function summarizeExecutionVariance(
  portfolio: LocalPortfolio,
  record: LocalAdviceRecord,
): ExecutionVarianceSummary {
  const reports = (portfolio.executionReports ?? []).filter((report) => report.adviceId === record.adviceId);
  const codes = new Set<AssetCode>([
    ...Object.keys(record.plannedAmounts ?? {}) as AssetCode[],
    ...reports.flatMap((report) => report.fills.map((fill) => fill.code)),
  ]);
  const rows = [...codes].map((code): ExecutionVarianceRow => {
    const plannedAmount = record.plannedAmounts?.[code] ?? 0;
    const fills = reports.flatMap((report) => report.fills).filter((fill) => fill.code === code);
    const actualAmount = fills.reduce((sum, fill) => sum + fill.shares * fill.price * (fill.side === 'BUY' ? 1 : -1), 0);
    const actualFee = fills.reduce((sum, fill) => sum + fill.fee, 0);
    return { code, plannedAmount, actualAmount, difference: actualAmount - plannedAmount, actualFee };
  });
  const plannedNotional = rows.reduce((sum, row) => sum + Math.abs(row.plannedAmount), 0);
  const actualNotional = rows.reduce((sum, row) => sum + Math.abs(row.actualAmount), 0);
  const plannedFees = Object.values(record.plannedEstimatedCosts ?? {}).reduce((sum, value) => sum + (value ?? 0), 0);
  const actualFees = rows.reduce((sum, row) => sum + row.actualFee, 0);
  const lastReport = [...reports].sort((left, right) => left.createdAt.localeCompare(right.createdAt)).at(-1);
  const postSnapshot = lastReport
    ? (portfolio.snapshots ?? []).find((item) => item.id === lastReport.postTradeSnapshotId)
    : undefined;
  const deviations = postSnapshot && postSnapshot.totalAssets > 0
    ? Object.entries(record.householdTargets).map(([rawCode, target]) => {
      const code = rawCode as AssetCode;
      return Math.abs((postSnapshot.values[code] ?? 0) / postSnapshot.totalAssets - (target ?? 0));
    })
    : [];
  return {
    available: Boolean(record.plannedAmounts),
    plannedNotional,
    actualNotional,
    completionRate: plannedNotional > 0 ? actualNotional / plannedNotional : null,
    plannedFees,
    actualFees,
    feeDifference: actualFees - plannedFees,
    maximumTargetDeviation: deviations.length ? Math.max(...deviations) : null,
    rows: rows.sort((left, right) => Math.abs(right.plannedAmount) - Math.abs(left.plannedAmount)),
  };
}
