function download(filename: string, content: string): void {
  const url = URL.createObjectURL(new Blob([content], { type: 'application/json' }));
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  URL.revokeObjectURL(url);
}

function renderInspector(advice: AdviceResult, code?: AssetCode): void {
  const asset = snapshot.assets.find((item) => item.code === code) ?? snapshot.assets[0];
  const inspector = document.querySelector<HTMLElement>('#asset-inspector');
  if (!asset || !inspector) return;
  const executionTarget = advice.rows.find((row) => row.code === asset.code)?.targetWeight ?? asset.confirmedTarget;
  const targetLabel = Math.abs(executionTarget - asset.confirmedTarget) > .00005
    ? `模型 ${percent(asset.confirmedTarget)} / 家庭约束后 ${percent(executionTarget)}`
    : percent(executionTarget);
  document.querySelectorAll('.asset-table tbody tr').forEach((row) => row.classList.toggle('active', (row as HTMLElement).dataset.code === asset.code));
  const equityCount = snapshot.assets.filter((item) => item.assetClass === 'EQUITY').length;
  const strength = asset.relativeStrength == null ? '防御资产不参与权益横截面排名' : asset.relativeStrength > .25 ? `在${equityCount}只权益 ETF 中相对较强` : asset.relativeStrength < -.25 ? `在${equityCount}只权益 ETF 中相对较弱` : `在${equityCount}只权益 ETF 中相对居中`;
  const trend = (asset.trendScore ?? 0) > .3 ? '多周期趋势偏正' : (asset.trendScore ?? 0) < -.3 ? '多周期趋势偏弱' : '多周期趋势分化';
  inspector.innerHTML = `<p class="eyebrow">${asset.assetClass === 'EQUITY' ? '权益资产' : asset.assetClass === 'GOLD' ? '黄金防御' : '国债防御'}</p><h3>${escapeHtml(instrumentLabel(asset.code, asset.name))}</h3><p><strong>组合意义：</strong>${escapeHtml(asset.role)}。${trend}；${strength}。</p><dl><div><dt>趋势评分</dt><dd>${number(asset.trendScore)}</dd></div><div><dt>20日 / 60日波动</dt><dd>${percent(asset.vol20)} / ${percent(asset.vol60)}</dd></div><div><dt>本期人工执行目标</dt><dd>${targetLabel}</dd></div><div><dt>月内临时观察</dt><dd>${percent(asset.provisionalTarget)}</dd></div></dl>`;
}

function bindPortfolioDialog(): void {
  const dialog = document.querySelector<HTMLDialogElement>('#portfolio-dialog');
  document.querySelectorAll<HTMLElement>('[data-open-portfolio]').forEach((button) => button.addEventListener('click', () => dialog?.showModal()));
  document.querySelectorAll<HTMLElement>('[data-close-dialog]').forEach((button) => button.addEventListener('click', () => dialog?.close()));
  document.querySelectorAll<HTMLButtonElement>('[data-ledger-step-button]').forEach((button) => button.addEventListener('click', () => {
    const step = button.dataset.ledgerStepButton;
    document.querySelectorAll('[data-ledger-step-button]').forEach((item) => item.classList.toggle('active', item === button));
    document.querySelectorAll<HTMLElement>('[data-ledger-step]').forEach((item) => item.classList.toggle('active', item.dataset.ledgerStep === step));
  }));
  const form = document.querySelector<HTMLFormElement>('#portfolio-form');
  form?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const data = new FormData(form);
    const now = new Date().toISOString();
    const capRaw = String(data.get('householdEquityCap') ?? '').trim();
    const liabilityRaw = String(data.get('liabilityEquityCap') ?? '').trim();
    const horizonRaw = String(data.get('horizonYears') ?? '').trim();
    const drawdownRaw = String(data.get('maxTolerableDrawdown') ?? '').trim();
    const nullableAmount = (name: string): number | null => {
      const raw = String(data.get(name) ?? '').trim();
      return raw === '' ? null : Math.max(0, Number(raw));
    };
    const qdiiCodes = snapshot.executionModel.qdiiCodes ?? snapshot.assets.filter((asset) => asset.qdii).map((asset) => asset.code);
    const qdiiPremiums = { ...(portfolio.qdiiPremiums ?? {}) };
    const qdiiPremiumUpdatedAtByCode = { ...(portfolio.qdiiPremiumUpdatedAtByCode ?? {}) };
    qdiiCodes.forEach((code) => {
      const raw = String(data.get(`premium-${code}`) ?? '').trim();
      const next = raw === '' ? null : Number(raw) / 100;
      if (qdiiPremiums[code] !== next) qdiiPremiumUpdatedAtByCode[code] = next == null ? null : now;
      else if (next != null && !qdiiPremiumUpdatedAtByCode[code]) qdiiPremiumUpdatedAtByCode[code] = now;
      qdiiPremiums[code] = next;
    });
    const positionInputs = ASSET_CODES.map((code): PositionInput => ({
      code,
      inputMode: data.get(`mode-${code}`) === 'QUANTITY' ? 'QUANTITY' : 'MARKET_VALUE',
      amount: Math.max(0, Number(data.get(code)) || 0),
    }));
    const flowType = data.get('cashFlowType');
    const flowAmount = Math.max(0, Number(data.get('cashFlowAmount')) || 0);
    const cashFlow: CashFlowInput | null = (flowType === 'CONTRIBUTION' || flowType === 'WITHDRAWAL') && flowAmount > 0 ? {
      type: flowType,
      amount: flowAmount,
      date: String(data.get('cashFlowDate') ?? now.slice(0, 10)),
      note: String(data.get('cashFlowNote') ?? '').trim(),
    } : null;
    portfolio = confirmPortfolio(
      portfolio,
      positionInputs,
      snapshot.assets,
      Math.max(0, Number(data.get('cash')) || 0),
      now,
      cashFlow,
    );
    portfolio = {
      ...portfolio,
      qdiiPremiums,
      qdiiPremiumUpdatedAtByCode,
      monthlyContribution: Math.max(0, Number(data.get('monthlyContribution')) || 0),
      plannedMonthlyContribution: Math.max(0, Number(data.get('monthlyContribution')) || 0),
    };
    const enabled = data.get('policyEnabled') === 'on';
    const confirmed = data.get('policyConfirm') === 'on';
    const emergencyFundReady = data.get('emergencyFundReady') === 'yes' ? true : data.get('emergencyFundReady') === 'no' ? false : null;
    const nextPolicyMaterial = {
      enabled,
      managedScope: String(data.get('managedScope') ?? '').trim(),
      emergencyFundReady,
      householdEquityCap: capRaw === '' ? null : Math.max(0, Math.min(1, Number(capRaw) / 100)),
      liabilityEquityCap: liabilityRaw === '' ? null : Math.max(0, Math.min(1, Number(liabilityRaw) / 100)),
      horizonYears: horizonRaw === '' ? null : Math.max(0, Number(horizonRaw)),
      maxTolerableDrawdown: drawdownRaw === '' ? null : Math.max(0, Number(drawdownRaw) / 100),
      contributionStability: ['LOW', 'MEDIUM', 'HIGH'].includes(String(data.get('contributionStability')))
        ? String(data.get('contributionStability')) as 'LOW' | 'MEDIUM' | 'HIGH'
        : 'UNSET' as const,
      reviewDueDate: String(data.get('reviewDueDate') ?? '') || null,
      expiresAt: String(data.get('policyExpiresAt') ?? '') || null,
      confirmedBy: String(data.get('confirmedBy') ?? '').trim(),
    };
    const oldPolicy = portfolio.ipsPolicy;
    const oldMaterial = oldPolicy ? {
      enabled: oldPolicy.enabled, managedScope: oldPolicy.managedScope, emergencyFundReady: oldPolicy.emergencyFundReady,
      householdEquityCap: oldPolicy.householdEquityCap, liabilityEquityCap: oldPolicy.liabilityEquityCap,
      horizonYears: oldPolicy.horizonYears, maxTolerableDrawdown: oldPolicy.maxTolerableDrawdown,
      contributionStability: oldPolicy.contributionStability, reviewDueDate: oldPolicy.reviewDueDate,
      expiresAt: oldPolicy.expiresAt, confirmedBy: oldPolicy.confirmedBy,
    } : null;
    const policyChanged = JSON.stringify(nextPolicyMaterial) !== JSON.stringify(oldMaterial);
    const defaultReview = new Date(Date.now() + 365 * 86_400_000).toISOString().slice(0, 10);
    const defaultExpiry = new Date(Date.now() + 395 * 86_400_000).toISOString().slice(0, 10);
    const confirmedAt = enabled
      ? confirmed ? now : policyChanged ? null : oldPolicy?.confirmedAt ?? null
      : null;
    const nextBucketsMaterial = {
      emergencyReserveExcluded: emergencyFundReady === true ? true : emergencyFundReady === false ? false : null,
      nearTermNeeds12Months: nullableAmount('needs12'),
      nearTermNeeds13To36Months: nullableAmount('needs36'),
      nearTermNeeds37To60Months: nullableAmount('needs60'),
      investableCash: Math.min(portfolio.cash, nullableAmount('investableCash') ?? 0),
    };
    const oldBuckets = portfolio.fundBuckets;
    const bucketChanged = JSON.stringify(nextBucketsMaterial) !== JSON.stringify(oldBuckets ? {
      emergencyReserveExcluded: oldBuckets.emergencyReserveExcluded,
      nearTermNeeds12Months: oldBuckets.nearTermNeeds12Months,
      nearTermNeeds13To36Months: oldBuckets.nearTermNeeds13To36Months,
      nearTermNeeds37To60Months: oldBuckets.nearTermNeeds37To60Months,
      investableCash: oldBuckets.investableCash,
    } : null);
    portfolio = {
      ...portfolio,
      schemaVersion: 6,
      ipsPolicy: {
        ...nextPolicyMaterial,
        reviewDueDate: enabled && confirmed ? nextPolicyMaterial.reviewDueDate ?? defaultReview : nextPolicyMaterial.reviewDueDate,
        expiresAt: enabled && confirmed ? nextPolicyMaterial.expiresAt ?? defaultExpiry : nextPolicyMaterial.expiresAt,
        status: !enabled ? 'UNSET' : confirmedAt ? 'CONFIRMED' : 'DRAFT',
        confirmedAt,
      },
      fundBuckets: {
        ...nextBucketsMaterial,
        confirmedAt: confirmed ? now : bucketChanged ? null : oldBuckets?.confirmedAt ?? null,
      },
      householdPolicy: {
        enabled,
        emergencyFundReady,
        householdEquityCap: nextPolicyMaterial.householdEquityCap,
        liabilityEquityCap: nextPolicyMaterial.liabilityEquityCap,
        horizonYears: nextPolicyMaterial.horizonYears,
        maxTolerableDrawdown: nextPolicyMaterial.maxTolerableDrawdown,
      },
    };
    await savePortfolio(portfolio);
    dialog?.close();
    render();
  });

  const status = document.querySelector<HTMLDivElement>('#dialog-status');
  const passwordInput = document.querySelector<HTMLInputElement>('#backup-password');
  document.querySelector('#export-backup')?.addEventListener('click', async () => {
    try {
      const now = new Date().toISOString();
      const candidate: LocalPortfolio = {
        ...portfolio,
        backupHealth: { status: 'PASS', lastExportAt: now, lastRestoreDryRunAt: now, message: '导出前加密—解密干跑校验通过' },
      };
      const encrypted = await encryptPortfolio(candidate, passwordInput?.value ?? '');
      const dryRun = normalizePortfolio(await decryptPortfolio(encrypted, passwordInput?.value ?? ''));
      const issues = validateLocalPortfolio(dryRun, snapshot.assets);
      if (issues.length) throw new Error(`备份恢复干跑失败：${issues.join('；')}`);
      portfolio = candidate;
      await savePortfolio(portfolio);
      download(`资产-家庭投资账本-${new Date().toISOString().slice(0, 10)}.json`, encrypted);
      if (status) status.textContent = '加密备份已生成，恢复干跑校验通过。';
    } catch (error) { if (status) status.textContent = error instanceof Error ? error.message : String(error); }
  });
  const fileInput = document.querySelector<HTMLInputElement>('#backup-file');
  const restorePreviewDialog = document.querySelector<HTMLDialogElement>('#restore-preview-dialog');
  const showRestorePreview = (restored: LocalPortfolio, origin: string): void => {
    pendingRestore = restored;
    const preview = document.querySelector<HTMLElement>('#restore-preview-summary');
    const total = Object.values(restored.values).reduce((sum, value) => sum + (value ?? 0), 0) + restored.cash;
    if (preview) preview.innerHTML = `<dl><div><dt>账本版本</dt><dd>schema ${restored.schemaVersion}</dd></div><div><dt>最近更新</dt><dd>${escapeHtml(restored.updatedAt.slice(0, 10))}</dd></div><div><dt>记录资产</dt><dd>${money(total)}</dd></div><div><dt>有效快照</dt><dd>${(restored.snapshots ?? []).filter((item) => !item.supersededBy).length}</dd></div><div><dt>建议 / 成交回报</dt><dd>${restored.adviceRecords?.length ?? 0} / ${restored.executionReports?.length ?? 0}</dd></div><div><dt>现金流</dt><dd>${restored.cashFlows?.length ?? 0}</dd></div></dl><p>${escapeHtml(origin)}。当前账本更新于 ${escapeHtml(portfolio.updatedAt.slice(0, 10))}；确认后仍会先为当前状态再建一个恢复点。</p>`;
    restorePreviewDialog?.showModal();
  };
  document.querySelector('#import-backup')?.addEventListener('click', () => fileInput?.click());
  fileInput?.addEventListener('change', async () => {
    try {
      const file = fileInput.files?.[0];
      if (!file) return;
      const restored = normalizePortfolio(await decryptPortfolio(await file.text(), passwordInput?.value ?? ''));
      const issues = validateLocalPortfolio(restored, snapshot.assets);
      if (issues.length) throw new Error(`备份账本校验失败：${issues.join('；')}`);
      showRestorePreview(restored, '加密备份已解密并通过结构校验');
    } catch (error) { if (status) status.textContent = error instanceof Error ? error.message : String(error); }
    finally { if (fileInput) fileInput.value = ''; }
  });
  document.querySelector('#restore-recovery-point')?.addEventListener('click', async () => {
    try {
      const id = portfolio.backupHealth?.lastRecoveryPointId;
      if (!id) throw new Error('当前没有可用的导入前恢复点');
      const recovery = await loadRecoveryPoint(id);
      if (!recovery) throw new Error('恢复点不存在或已被浏览器清理');
      const restored = normalizePortfolio(recovery.portfolio);
      const issues = validateLocalPortfolio(restored, snapshot.assets);
      if (issues.length) throw new Error(`恢复点校验失败：${issues.join('；')}`);
      showRestorePreview(restored, `恢复点创建于 ${recovery.createdAt.slice(0, 19).replace('T', ' ')}`);
    } catch (error) { if (status) status.textContent = error instanceof Error ? error.message : String(error); }
  });
  document.querySelectorAll<HTMLElement>('[data-cancel-restore]').forEach((button) => button.addEventListener('click', () => {
    pendingRestore = null;
    restorePreviewDialog?.close();
  }));
  document.querySelector('#confirm-restore')?.addEventListener('click', async () => {
    if (!pendingRestore) return;
    try {
      const now = new Date().toISOString();
      const recovery = await saveRecoveryPoint(portfolio, now);
      portfolio = {
        ...pendingRestore,
        backupHealth: {
          ...(pendingRestore.backupHealth ?? { lastExportAt: null, lastRestoreDryRunAt: null }),
          status: 'PASS',
          lastImportPreviewAt: now,
          lastRestoreDryRunAt: now,
          lastRestoredAt: now,
          lastRecoveryPointId: recovery.id,
          lastRecoveryPointAt: recovery.createdAt,
          message: '导入预览、完整性校验与覆盖前恢复点均已通过',
        },
      };
      pendingRestore = null;
      await savePortfolio(portfolio);
      restorePreviewDialog?.close();
      dialog?.close();
      render();
    } catch (error) {
      if (status) status.textContent = error instanceof Error ? error.message : String(error);
    }
  });
}

function bindInteractions(advice: AdviceResult): void {
  bindPortfolioDialog();
  document.querySelectorAll<HTMLButtonElement>('[data-asset-code]').forEach((button) => button.addEventListener('click', () => {
    renderInspector(advice, button.dataset.assetCode as AssetCode);
  }));
  renderInspector(advice, snapshot.assets[0]?.code);
  if (page === 'market' && marketSeries) bindMarketWorkspace(marketSeries, snapshot);
  if (page === 'risk') bindAssetOverview(performance);
  if (page === 'asset-cycle' && assetCycle) bindAssetCycleBoard(assetCycle);

  document.querySelector<HTMLElement>('[data-clear-portfolio]')?.addEventListener('click', async () => {
    if (!window.confirm(`确定清除当前浏览器保存的${snapshot.assets.length}只 ETF 持仓、现金和溢价吗？加密备份不会被删除。`)) return;
    portfolio = emptyPortfolio();
    await savePortfolio(portfolio);
    render();
  });

  document.querySelectorAll<HTMLButtonElement>('[data-void-cashflow]').forEach((button) => button.addEventListener('click', async () => {
    if (!window.confirm('确定作废这笔外部现金流吗？原记录和更正痕迹会保留在本机审计账本中。')) return;
    try {
      portfolio = voidCashFlow(portfolio, button.dataset.voidCashflow ?? '', new Date().toISOString());
      await savePortfolio(portfolio);
      render();
    } catch (error) {
      window.alert(error instanceof Error ? error.message : String(error));
    }
  }));

  document.querySelector<HTMLButtonElement>('[data-record-advice]')?.addEventListener('click', async () => {
    try {
      const { record, deferrals } = buildAdviceAuditRecord(portfolio, snapshot, advice);
      portfolio = appendAdviceRecord(portfolio, record, deferrals);
      await savePortfolio(portfolio);
      render();
    } catch (error) {
      window.alert(error instanceof Error ? error.message : String(error));
    }
  });

  const executionDialog = document.querySelector<HTMLDialogElement>('#execution-dialog');
  document.querySelectorAll<HTMLElement>('[data-close-execution]').forEach((button) => button.addEventListener('click', () => executionDialog?.close()));
  document.querySelectorAll<HTMLButtonElement>('[data-advice-status]').forEach((button) => button.addEventListener('click', async () => {
    try {
      const status = button.dataset.adviceStatus;
      const adviceId = button.dataset.adviceId ?? '';
      if (!['PARTIAL', 'EXECUTED', 'SKIPPED'].includes(status ?? '')) throw new Error('建议状态无效');
      if (status === 'PARTIAL' || status === 'EXECUTED') {
        const form = document.querySelector<HTMLFormElement>('#execution-form');
        const record = portfolio.adviceRecords?.find((item) => item.adviceId === adviceId);
        if (!form || !record) throw new Error('建议记录不存在');
        (form.elements.namedItem('executionAdviceId') as HTMLInputElement).value = adviceId;
        (form.elements.namedItem('executionStatus') as HTMLInputElement).value = status;
        (form.elements.namedItem('executionCashAfter') as HTMLInputElement).value = portfolio.cash ? String(portfolio.cash) : '';
        ASSET_CODES.forEach((code) => {
          const shares = record.executableShares[code] ?? 0;
          (form.elements.namedItem(`fill-side-${code}`) as HTMLSelectElement).value = shares < 0 ? 'SELL' : 'BUY';
          (form.elements.namedItem(`fill-shares-${code}`) as HTMLInputElement).value = shares ? String(Math.abs(shares)) : '';
        });
        executionDialog?.showModal();
        return;
      }
      const note = window.prompt('请简要记录跳过原因（不会自动交易）：', '家庭本期决定不执行') ?? '';
      if (!note.trim()) return;
      portfolio = appendAdviceStatus(portfolio, adviceId, 'SKIPPED', new Date().toISOString(), note);
      await savePortfolio(portfolio);
      render();
    } catch (error) {
      window.alert(error instanceof Error ? error.message : String(error));
    }
  }));

  document.querySelector<HTMLFormElement>('#execution-form')?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const form = event.currentTarget as HTMLFormElement;
    const data = new FormData(form);
    const fills = ASSET_CODES.flatMap((code): ExecutionFill[] => {
      const shares = Number(data.get(`fill-shares-${code}`)) || 0;
      if (shares <= 0) return [];
      return [{
        code,
        side: data.get(`fill-side-${code}`) === 'SELL' ? 'SELL' : 'BUY',
        shares,
        price: Number(data.get(`fill-price-${code}`)) || 0,
        fee: Number(data.get(`fill-fee-${code}`)) || 0,
      }];
    });
    try {
      portfolio = recordExecutionReport(portfolio, {
        adviceId: String(data.get('executionAdviceId') ?? ''),
        status: data.get('executionStatus') === 'EXECUTED' ? 'EXECUTED' : 'PARTIAL',
        tradeDate: String(data.get('executionTradeDate') ?? ''), fills,
        actualCashAfter: Number(data.get('executionCashAfter')),
        note: String(data.get('executionNote') ?? ''),
      }, snapshot.assets, new Date().toISOString());
      await savePortfolio(portfolio);
      executionDialog?.close();
      render();
    } catch (error) {
      const status = document.querySelector<HTMLElement>('#execution-status');
      if (status) status.textContent = error instanceof Error ? error.message : String(error);
    }
  });

  document.querySelectorAll<HTMLButtonElement>('[data-deferral-status]').forEach((button) => button.addEventListener('click', async () => {
    try {
      const next = button.dataset.deferralStatus;
      if (next !== 'REVIEWED' && next !== 'RELEASED') throw new Error('延期状态无效');
      portfolio = appendDeferralStatus(portfolio, button.dataset.deferralId ?? '', next, new Date().toISOString(), '家庭人工复核');
      await savePortfolio(portfolio);
      render();
    } catch (error) { window.alert(error instanceof Error ? error.message : String(error)); }
  }));

  document.querySelector<HTMLFormElement>('#monthly-review-form')?.addEventListener('submit', async (event) => {
    event.preventDefault();
    const operation = deriveHouseholdOperation(snapshot, portfolio, advice);
    const incompletePrerequisite = operation.steps.slice(0, -1).find((step) => step.status !== 'DONE');
    if (incompletePrerequisite) {
      window.alert(`请先完成：${incompletePrerequisite.label}`);
      return;
    }
    const data = new FormData(event.currentTarget as HTMLFormElement);
    const checks = ['dataChecked', 'holdingsChecked', 'policyChecked', 'premiumChecked', 'adviceChecked'];
    if (!checks.every((name) => data.get(name) === 'on')) {
      window.alert('请完成五项月度检查后再保存。');
      return;
    }
    const now = new Date().toISOString();
    try {
      portfolio = appendMonthlyReview(portfolio, {
        id: `monthly-${snapshot.meta.confirmedSignalDate.slice(0, 7)}-${now.replace(/\D/g, '').slice(0, 14)}`,
        month: snapshot.meta.confirmedSignalDate.slice(0, 7), createdAt: now,
        dataChecked: true, holdingsChecked: true, policyChecked: true,
        premiumChecked: true, adviceChecked: true,
        note: String(data.get('reviewNote') ?? '').trim(),
      });
      await savePortfolio(portfolio);
      render();
    } catch (error) { window.alert(error instanceof Error ? error.message : String(error)); }
  });

  document.querySelectorAll<HTMLButtonElement>('[data-operation-action]').forEach((button) => button.addEventListener('click', () => {
    const action = button.dataset.operationAction;
    const ledgerStep = action === 'OPEN_POLICY' ? 'policy' : action === 'OPEN_PREMIUM' || action === 'OPEN_HOLDINGS' ? 'holdings' : null;
    if (ledgerStep) {
      document.querySelector<HTMLDialogElement>('#portfolio-dialog')?.showModal();
      document.querySelector<HTMLButtonElement>(`[data-ledger-step-button="${ledgerStep}"]`)?.click();
      return;
    }
    const selector = action === 'REVIEW_ADVICE' ? '#monthly-advice'
      : action === 'RECORD_EXECUTION' ? '#execution-history'
        : action === 'COMPLETE_REVIEW' ? '#monthly-review-form' : null;
    if (selector) document.querySelector(selector)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }));

  const tocLinks = Array.from(document.querySelectorAll<HTMLAnchorElement>('.document-toc a[href^="#"]'));
  const headings = tocLinks.map((link) => document.getElementById(decodeURIComponent(link.hash.slice(1)))).filter((item): item is HTMLElement => Boolean(item));
  if (headings.length && 'IntersectionObserver' in window) {
    const observer = new IntersectionObserver((entries) => entries.forEach((entry) => {
      if (!entry.isIntersecting) return;
      tocLinks.forEach((link) => link.classList.toggle('active', link.hash === `#${entry.target.id}`));
    }), { rootMargin: '-18% 0px -72% 0px' });
    headings.forEach((heading) => observer.observe(heading));
  }

  requestAnimationFrame(() => document.querySelectorAll('.reveal').forEach((element) => element.classList.add('visible')));
}

function render(): void {
  performance = calculatePerformance(portfolio, marketSeries);
  const advice = calculateAdvice(portfolio, snapshot.assets, snapshot.executionModel, {
    ...snapshot.health,
    targetStatus: snapshot.meta.targetStatus,
    confirmedSignalDate: snapshot.meta.confirmedSignalDate,
    confirmedEffectiveDate: snapshot.meta.confirmedEffectiveDate,
  });
  const model = page === 'model' ? renderMarkdown(modelSource) : undefined;
  const content = page === 'asset-cycle'
    ? assetCycle
      ? renderAssetCyclePage(assetCycle, assetCycleHealth)
      : renderAssetCycleUnavailablePage(assetCycleError || '资产周期研究数据暂时不可用', assetCycleHealth)
    : renderPage({ page, root, snapshot, portfolio, advice, model, market: marketSeries, performance, publicationObservations });
  app.innerHTML = renderShell({ page, root, snapshot, portfolio, content, dialog: portfolioDialog(snapshot, portfolio) });
  app.setAttribute('aria-busy', 'false');
  bindInteractions(advice);
}

async function bootstrap(): Promise<void> {
  try {
    const needsMarket = ['market', 'risk', 'data'].includes(page);
    const [resourcesResult, saved, assetCycleResponse, assetCycleHealthResponse] = await Promise.all([
      loadNetworkResources(root, { market: needsMarket, model: page === 'model' }).catch(async (error) => {
        const cached = await loadLastCompleteBundle();
        if (!cached) throw error;
        cached.snapshot.health = {
          status: 'DATA ERROR', blocking: true,
          summary: `网络数据不可用，当前显示上次完整数据包 ${cached.buildId}；仅供只读复核`,
          issues: [...cached.snapshot.health.issues, {
            type: 'OFFLINE_LAST_COMPLETE', label: '离线只读回退', severity: 'ERROR', code: 'PORTFOLIO',
            details: error instanceof Error ? error.message : String(error),
          }],
        };
        return cached;
      }),
      loadPortfolio(),
      page === 'asset-cycle' ? fetch(`${root}data/asset-cycle.json`, { cache: 'no-store' }).catch(() => null) : Promise.resolve(null),
      page === 'asset-cycle' ? fetch(`${root}data/asset-cycle-health.json`, { cache: 'no-store' }).catch(() => null) : Promise.resolve(null),
    ]);
    snapshot = resourcesResult.snapshot;
    if (snapshot.meta.schemaVersion !== '4.0') throw new Error('数据契约版本不兼容：资产 V5 只接受正式 4.0 公开快照');
    const snapshotAgeHours = (Date.now() - new Date(snapshot.meta.generatedAt).getTime()) / 3_600_000;
    if (!Number.isFinite(snapshotAgeHours) || snapshotAgeHours > snapshot.executionModel.freshness.snapshotMaxAgeHours) {
      snapshot.health = {
        status: 'DATA ERROR',
        blocking: true,
        summary: `公开快照已超过 ${snapshot.executionModel.freshness.snapshotMaxAgeHours} 小时未更新，暂停新的人工建议`,
        issues: [...snapshot.health.issues, { type: 'STALE_SNAPSHOT', label: '公开快照过期', severity: 'ERROR', code: 'PORTFOLIO', details: `生成时间 ${snapshot.meta.generatedAt}` }],
      };
    }
    const modelAudit = auditSnapshotModel(snapshot);
    if (!modelAudit.passed) {
      snapshot.health = {
        status: 'DATA ERROR', blocking: true,
        summary: `模型完整性审计失败：${modelAudit.issues.join('；')}`,
        issues: [...snapshot.health.issues, ...modelAudit.issues.map((details) => ({
          type: 'MODEL_AUDIT', label: '模型完整性审计', severity: 'ERROR', code: 'PORTFOLIO', details,
        }))],
      };
    }
    if (!snapshot.health.blocking && resourcesResult.source !== 'LAST_COMPLETE') await saveLastCompleteBundle(resourcesResult);
    publicationObservations = await recordPublicationObservation(resourcesResult).catch(() => []);
    const normalized = normalizePortfolio(saved as LocalPortfolio);
    portfolio = applyLifecycleExpirations(normalized, new Date().toISOString());
    if (JSON.stringify(portfolio) !== JSON.stringify(normalized)) await savePortfolio(portfolio);
    if (page === 'model') modelSource = resourcesResult.modelSource ?? '';
    if (needsMarket && resourcesResult.marketSeries) {
      marketSeries = resourcesResult.marketSeries;
      if (!['1.0', '2.0'].includes(marketSeries.schemaVersion)) throw new Error('行情数据契约版本不兼容');
    }
    if (page === 'asset-cycle') {
      if (assetCycleHealthResponse?.ok) {
        try {
          assetCycleHealth = parseAssetCycleHealth(await assetCycleHealthResponse.json());
        } catch (error) {
          assetCycleError = error instanceof Error ? error.message : String(error);
        }
      }
      if (!assetCycleResponse?.ok) {
        assetCycleError = `资产周期数据读取失败${assetCycleResponse ? `（HTTP ${assetCycleResponse.status}）` : '（网络不可用）'}`;
      } else {
        try {
          assetCycle = parseAssetCycleDataset(await assetCycleResponse.json());
        } catch (error) {
          assetCycleError = error instanceof Error ? error.message : String(error);
        }
      }
    }
    render();
  } catch (error) {
    app.setAttribute('aria-busy', 'false');
    app.innerHTML = `<div class="fatal"><p>数据异常</p><h1>暂时无法打开资产工作台</h1><p>${escapeHtml(error instanceof Error ? error.message : String(error))}</p><button class="quiet-button" onclick="location.reload()">重新加载</button></div>`;
  }
}

void bootstrap();
